(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c35"]=[{"id":"00014625","register_sub_id":"101","register_pk":"515167","name":"明楽寺鐘楼","kana":"みょうらくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.50500833,"lng":136.22634167,"geo_status":"db","era":"天保8年（1837）","year":1837,"year_source":"db","year_min":1837,"year_max":1837,"year_label":null,"structure":"木造、瓦葺、面積14㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0519","desc":"本堂の南西に東面し、切石積基壇に建つ鐘楼。方一間の入母屋造桟瓦葺で、内転びの円柱を貫で固め、組物は尾垂木付の二手先、軒は二軒繁垂木とする。梵鐘を虹梁から吊り、天井は小組格天井を張る。小規模ながら欄間や木鼻などを彫刻で飾った丁寧な造りの鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014625"},{"id":"00014623","register_sub_id":"101","register_pk":"515165","name":"明楽寺太鼓楼","kana":"みょうらくじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.504975,"lng":136.22623611,"geo_status":"db","era":"文化4年（1807）","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0517","desc":"本堂の南西に北面する太鼓楼。二階建入母屋造妻入桟瓦葺、組物は出三斗、中備は蟇股、軒は一軒繁垂木。二階は北と南に火灯窓、東と西は格子構え、腰は袴腰形板張。内部は北西に階段を設け二階に太鼓を吊る。高く聳える望楼が歴史的な伽藍を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014623"},{"id":"00014621","register_sub_id":"101","register_pk":"515163","name":"明楽寺本堂","kana":"みょうらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.50526389,"lng":136.22661111,"geo_status":"db","era":"安永年間（1772-1781）","year":1776,"year_source":"estimated","year_min":1772,"year_max":1781,"year_label":"安永年間（1772-1781）","structure":"木造平屋建、瓦葺、建築面積697㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0515","desc":"木之本宿の中心に位置する真宗大谷派寺院の本堂。西面する入母屋造平入桟瓦葺で向拝を付す。間取は内外陣と左右余間とし、外陣周囲は板敷広縁に落縁を付す。外陣には円柱を立登らせ、虹梁形差物上に蟇股を配す。宿場の歴史的景観を担う大規模寺院本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014621"},{"id":"00006570","register_sub_id":"101","register_pk":"107553","name":"八阪神社本殿","kana":"やさかじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町柞原321","lat":34.86350078,"lng":136.026695,"geo_status":"db","era":"貞享5","year":1688,"year_source":"db","year_min":1688,"year_max":1688,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積10㎡、覆屋付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0240","desc":"信楽川左岸の山裾に南面して建つ。正面柱間７．５尺規模の一間社流造で，屋根は檜皮葺。現在は覆屋に納める。浜床付で木階７級を設ける。妻飾りは虹梁大瓶束。正面は格子戸４枚の引違い，内陣は弊軸付板扉で限る。獏形木鼻や蟇股の彫刻で飾り，極彩色が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006570"},{"id":"00003248","register_sub_id":"101","register_pk":"104238","name":"二童子神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町中野140","lat":34.85912608,"lng":136.02055673,"geo_status":"db","era":"元禄16","year":1703,"year_source":"db","year_min":1703,"year_max":1703,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0208","desc":"一間社春日造の社殿。形式・棟札等から元禄１６年の建築であることが知られる。身舎は方１間で，ほぼ均等に内陣と下陣に分ける。屋根は檜皮葺とし，箱棟を置いている。滋賀県下でも数の少ない春日造本殿であり，近世本殿建築の好例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003248"},{"id":"00004138","register_sub_id":"101","register_pk":"105128","name":"八幡神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小田苅町954","lat":35.13378204,"lng":136.2205683,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、檜皮葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"25 － 0230","desc":"三間社流造の社殿。身舎は奥行２間の外陣と奥行１間の内陣からなり，格天井とする。正側面には縁を巡らし，背面柱筋には脇障子を設ける。屋根は銅板葺で，正面に角柱の向拝を設ける。全体構成に中世の様式の影響を残す，小規模社殿の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004138"},{"id":"00012959","register_sub_id":"101","register_pk":"368039","name":"阿倍王子神社旧本殿","kana":"あべおうじじんじゃきゅうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町160","lat":34.63089722,"lng":135.50900833,"geo_status":"db","era":"明治41年／昭和43年移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.2㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 767","desc":"市南部の熊野街道沿いにある神社で、旧本殿は境内南辺の切石積基壇上に東面して建つ。正面一間、側背面二間、流造銅板葺。庇は一段折れて縋破風とし、軒唐破風を付す。身舎組物は舟肘木。側面中柱は棟木まで延びあがる。簡素ながら特異なつくりの社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012959"},{"id":"00012960","register_sub_id":"101","register_pk":"368040","name":"阿倍王子神社葛之葉稲荷神社本殿（旧男山八幡神社本殿）","kana":"あべおうじじんじゃくずのはいなりじんじゃほんでん（きゅうおとこやまはちまんじんじゃほんでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町160","lat":34.63109722,"lng":135.50927778,"geo_status":"db","era":"江戸後期／明治41年・昭和44年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 768","desc":"拝殿東側の覆屋内に南面して建つ。正面一間、側面二間、入母屋造檜皮葺、向拝軒唐破風付で、やや横長の平面とし、向拝の連三斗は肘木を内側に延ばして菖蒲桁下の出三斗とつなぐ。全体を赤色塗として要所に極彩色を施す。小社ながら華麗な意匠の社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012960"},{"id":"00012963","register_sub_id":"101","register_pk":"368043","name":"安倍晴明神社透塀","kana":"あべせいめいじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町144","lat":34.631725,"lng":135.50934167,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、銅板葺、延長25m","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 771","desc":"拝殿の背面から延び、本殿の四周を結界する木造銅板葺の透塀。面取角柱を腰長押と内法長押で固め、腰上は菱形断面の板連子、腰は縦板張とする。屋根は腕木を出して桁を通し、一軒疎垂木とする。良材を用いた精巧なつくりで、本殿周辺の景観を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012963"},{"id":"00012962","register_sub_id":"101","register_pk":"368042","name":"安倍晴明神社拝殿及び幣殿","kana":"あべせいめいじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町144","lat":34.63174167,"lng":135.50923889,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 770","desc":"本殿前に西面して建つ。正面三間、側面三間、入母屋造銅板葺。三方に高欄付の縁を廻し、背面中央に奥行二間の幣殿を突出して本殿を臨む。内部は一室で左右奥に神饌所と祭器庫を設ける。本殿と調和した端正な復古的意匠で、落ち着いた社頭景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012962"},{"id":"00012961","register_sub_id":"101","register_pk":"368041","name":"安倍晴明神社本殿","kana":"あべせいめいじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町144","lat":34.63175,"lng":135.50931389,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 769","desc":"市南部の熊野街道沿いにある神社で、本殿は境内奥の切石積基壇上に西面して建つ。一間社流造銅板葺。大仏様木鼻や中世風蟇股を用いて細部を古式に飾る。身舎正面は柱筋内側に板扉を立てる。もと奈良県技師・吉田種次郎の設計による、技巧を凝らした近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012961"},{"id":"00010671","register_sub_id":"101","register_pk":"201245","name":"蟻通神社裏門","kana":"ありとおしじんじゃうらもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385812,"lng":135.313315,"geo_status":"db","era":"嘉永6年(1853)／昭和17年移築","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造、瓦葺、間口4.0m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0626","desc":"本殿北西側の参道口に構える四脚門で、切妻造本瓦葺である。表門とほぼ同規模同形式になり、同様に赤色塗とするが、棟柱の柱頭に雲紋の笈形を付さない点のみ異なる。大工の貝戸彦左衛門清重は当地の大工組の組頭を務めた。表門とともに神域を画す門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010671"},{"id":"00010669","register_sub_id":"101","register_pk":"201243","name":"蟻通神社絵馬殿","kana":"ありとおしじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385257,"lng":135.313414,"geo_status":"db","era":"文久元年(1861)／昭和17年移築","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0624","desc":"境内南東寄りに南北棟で建つ絵馬殿で、桁行四間梁間二間、入母屋造本瓦葺である。円柱を絵様虹梁で繋いで各間に大瓶束を立て、柱と大瓶束上に大斗舟肘木を組む。建ちの高い立面、透彫の虹梁木鼻や持送などに時代性を示すとともに、往時の信仰形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010669"},{"id":"00010670","register_sub_id":"101","register_pk":"201244","name":"蟻通神社表門","kana":"ありとおしじんじゃおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385239,"lng":135.313256,"geo_status":"db","era":"嘉永5年(1852)／昭和17年移築","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造、瓦葺、間口4.0m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0625","desc":"境内入口に南面して建つ赤塗の四脚門で、切妻造本瓦葺である。円柱を梁行のみ貫で固め、正背面柱は大斗舟肘木で桁を受ける。棟柱では桁高さの矩形梁を絵様肘木で受け、柱頭間に虹梁を渡す。また柱頭に雲紋の笈形を、大斗上に同種の拳鼻を付し、華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010670"},{"id":"00010673","register_sub_id":"101","register_pk":"201247","name":"蟻通神社北手水舎","kana":"ありとおしじんじゃきたてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385897,"lng":135.313451,"geo_status":"db","era":"江戸末期／昭和17年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積6.5㎡、手水鉢付","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0628","desc":"裏門北側に南北棟で建つ手水舎で、南寄りに手水鉢を据え、北を井戸とする。軸部は内転びの角柱を頭貫と台輪で固め、両妻は絵様虹梁上に笈形付の大瓶束を立てて飾る。頭貫を受ける大振りの持送や頭貫木鼻は絵馬殿同様に透彫の絵様を施す。装飾性豊かな手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010673"},{"id":"00010667","register_sub_id":"101","register_pk":"201241","name":"蟻通神社後門及び東西透塀","kana":"ありとおしじんじゃごうもんおよびとうざいすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385724,"lng":135.313465,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"後門 木造、銅板葺、間口2.4m 東透塀 木造、銅板葺、総延長24m 西透塀 木造、銅板葺、総延長24m","structure_material":"後門 木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0622","desc":"本殿背後に建つ後門と、東西に本殿を囲み拝殿背面にいたる透塀で、整層積の石垣上に建つ。後門は一間腕木門で両折桟唐戸を吊り、楣上に足の長い蟇股を配す。透塀は柱間に尖頭形の竪板を張詰め、上部目透しとする。透廊とともに社地移転時の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010667"},{"id":"00010666","register_sub_id":"101","register_pk":"201240","name":"蟻通神社透廊","kana":"ありとおしじんじゃすきろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385631,"lng":135.313426,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0621","desc":"幣殿に接続して石垣上に建つ桁行一一間の透廊で、中央間を広めて後方本殿側に拝所を張出す。東西両端を室とする他は吹放しで、切妻造銅板葺である。角柱上に大斗実肘木を乗せ、梁上に蟇股を配す以外は簡明な意匠である。社地移転時の境内の変容を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010666"},{"id":"00010674","register_sub_id":"101","register_pk":"201248","name":"蟻通神社太鼓橋","kana":"ありとおしじんじゃたいこばし","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385174,"lng":135.313176,"geo_status":"db","era":"江戸末期／昭和17年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造桁橋、橋長3.9m、幅員2.6m、袖高欄付","structure_material":"石造桁橋","registered":"2015.08.04(平成27.08.04)","register_no":"27－0629","desc":"表門手前の池に架かる石橋。橋長三・九メートル幅員二・六メートルの桁橋で、中央の橋脚にアーチ状の桁を架けて太鼓橋形式とする。橋面両側にアーチ状の石製高欄を組み、前後に袖高欄を設け、高欄の込栭を分銅形に作る。参道に趣を添える石橋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010674"},{"id":"00010665","register_sub_id":"101","register_pk":"201239","name":"蟻通神社拝殿及び幣殿","kana":"ありとおしじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385549,"lng":135.31339,"geo_status":"db","era":"江戸末期／明治40年改修・昭和17年移築改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0620","desc":"本殿正面に建ち、桁行一一間の横長平面になる入母屋造本瓦葺の拝殿。戦中の移築時に、正面中央の唐破風造向拝と背面の幣殿を増築した。側廻りは開口を多くして開放的とし、内部は天井を張らず、力感ある梁組を現しとする。市内で希少な横長形式の近世拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010665"},{"id":"00010664","register_sub_id":"101","register_pk":"201238","name":"蟻通神社本殿","kana":"ありとおしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.38568,"lng":135.313448,"geo_status":"db","era":"寛文9年(1669)／昭和17年移築・昭和25年改修","year":1669,"year_source":"db","year_min":1669,"year_max":1669,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.6㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0619","desc":"境内北寄りの透塀内に南面する。正面一間側面二間、隅木入春日造、軒唐破風付、銅板葺で、三方に腰高に縁高欄を廻らし、正面に浜床を設ける。身舎は組物出組で板支輪に波紋などを陽刻し、庇では二重虹梁に蟇股と大瓶束を置くなど、要所を彫刻で飾る本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010664"},{"id":"00010668","register_sub_id":"101","register_pk":"201242","name":"蟻通神社舞殿","kana":"ありとおしじんじゃまいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385437,"lng":135.313337,"geo_status":"db","era":"江戸前期／昭和17年移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、銅板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0623","desc":"拝殿前方に建つ。五・八メートル四方の方一間、吹放し形式の舞殿で、入母屋造妻入り、銅板葺である。柱と頭貫を持送で固め、台輪上の組物は柱上、中備とも三斗で中備には拳鼻を付す。床高はやや低めとし、棹縁天井を張る。境内景観の中核をなす、大型の舞殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010668"},{"id":"00010672","register_sub_id":"101","register_pk":"201246","name":"蟻通神社南手水舎","kana":"ありとおしじんじゃみなみてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385122,"lng":135.313084,"geo_status":"db","era":"昭和15年／昭和17年移築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造、瓦葺、面積7.4㎡、手水鉢付","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0627","desc":"参道脇に南北棟で建つ、桁行二間で切妻造本瓦葺の手水舎。吹放し形式で、北側に大型で元禄七年銘の手水鉢を据え、南を井戸とする。軸部は柱を内転びに立てて貫で固め、柱上に大斗実肘木を組み、桁と梁を受ける。神社境内入口の景観形成に寄与する手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010672"},{"id":"00015334","register_sub_id":"101","register_pk":"532458","name":"石切劔箭神社絵馬殿","kana":"いしきりつるぎやじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府東大阪市東石切町一丁目736他","lat":34.681325,"lng":135.64626389,"geo_status":"db","era":"昭和35年","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造2階建、銅板葺、建築面積83㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0945","desc":"境内入口に建ち、門を兼ねた絵馬殿。梁間四間と奥行深い三間一戸の楼門形式で、屋根銅板葺で、切妻造の四周に庇を付し棟上に剣と矢を飾る。下層中央間両脇に絵馬を並べ、随身像を安置。上層は格天井の一室で長押を廻らす。独創的な意匠とした楼門風の絵馬殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015334"},{"id":"00015333","register_sub_id":"101","register_pk":"532457","name":"石切劔箭神社透塀","kana":"いしきりつるぎやじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市東石切町一丁目691","lat":34.68217778,"lng":135.6462,"geo_status":"db","era":"昭和6年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造、銅板葺、総延長26m","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0944","desc":"拝殿の背面から本殿の背面の柱筋に至り、矩折に本殿両脇を囲繞する銅板葺の透塀。切石積基壇に建ち、隅に角柱、中間に円柱を立て、地長押・腰長押・内法長押を打ち、腰は竪板張、上部は連子窓。腕木と垂木の鼻先に付した繰型が特徴的で、軒廻り賑やかな透塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015333"},{"id":"00015332","register_sub_id":"101","register_pk":"532456","name":"石切劔箭神社拝殿及び幣殿","kana":"いしきりつるぎやじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市東石切町一丁目691","lat":34.68224167,"lng":135.64626389,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0943","desc":"本殿の前方、基壇上に建つ拝殿及び幣殿。設計は吉田種次郎。全体Ｔ字形平面で、拝殿入母屋造、幣殿両下造で銅板葺。正面に千鳥破風を据え、向唐破風造向拝を付す。組物に舟肘木や挿肘木、木鼻に拳鼻や大仏様風の繰形を用いるなど細部まで意匠を凝らした社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015332"},{"id":"00015331","register_sub_id":"101","register_pk":"532455","name":"石切劔箭神社本殿","kana":"いしきりつるぎやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市東石切町一丁目691","lat":34.68229722,"lng":135.64625833,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0942","desc":"生駒山西麓に位置する神社本殿。設計は吉田種次郎。高い基壇に建つ三間社流造銅板葺で、正面に千鳥・軒唐破風を付し、両妻面に亀甲紋の雨除を設ける。組物は大仏様風の木鼻を用いた特異な一手先とするなど、中世寺社建築の細部意匠を引用した近代の神社本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015331"},{"id":"00001393","register_sub_id":"101","register_pk":"102383","name":"大阪天満宮神楽所","kana":"おおさかてんまんぐうかぐらしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市北区天神橋2-1-8","lat":34.69598155,"lng":135.51294852,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"27 － 0077","desc":"弘化２年（1845）造替の本殿・拝殿の東に建つ南北棟，銅板葺入母屋屋根の単層建物で，拝殿とは二階廊で連絡する。柱上には舟肘木を置き，軒は二軒疎角垂木とし，周囲に高く縁を回し，擬宝珠高欄を付ける。西面は，格子蔀戸を釣るなど古式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001393"},{"id":"00001394","register_sub_id":"101","register_pk":"102384","name":"大阪天満宮参集所","kana":"おおさかてんまんぐうさんしゅうじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市北区天神橋2-1-8","lat":34.696095,"lng":135.513077,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積231㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"27 － 0078","desc":"本殿と梅花殿の間に建つ東西棟，銅板葺入母屋屋根，木造単層の建物で，神楽所とは軒を一段落として変化をつけ，梅花殿とは廊下で繋がれる。身舎・庇構成をとり，身舎桁行を３分して計５室を設ける。通称「広間」で，現在は梅花殿の控室として利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001394"},{"id":"00001392","register_sub_id":"101","register_pk":"102382","name":"大阪天満宮梅花殿","kana":"おおさかてんまんぐうばいかでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市北区天神橋2-1-8","lat":34.69607279,"lng":135.5133448,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積129㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"27 － 0076","desc":"「天満の天神さん」として知られる大阪天満宮の境内東端中央寄りに南面して建つ。木造単層，銅板葺入母屋屋根の客殿（現在は結婚式場）で，身舎・庇構成をとり，東端の部屋の天井を支輪付二重折上小組格天井とした格式高い造りとする点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001392"},{"id":"00011988","register_sub_id":"101","register_pk":"211159","name":"男神社旧拝殿及び幣殿（社務所）","kana":"おのじんじゃきゅうはいでんおよびへいでん（しゃむしょ）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府泉南市男里三丁目1065","lat":34.359304,"lng":135.257246,"geo_status":"db","era":"明治15年／明治36年改修、昭和15年頃移築","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"27-711","desc":"割拝殿として建築されたものを移築し社務所とする。桁行五間、梁間二間、切妻造、銅板葺で、正面に千鳥破風を付け、唐破風の玄関を張り出す。玄関は平三斗と太瓶束上の実肘木で軒桁を受ける凝った意匠を見せ、当地方の特色を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011988"},{"id":"00011989","register_sub_id":"101","register_pk":"211160","name":"男神社透塀","kana":"おのじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府泉南市男里三丁目1065","lat":34.35944239,"lng":135.25753876,"geo_status":"db","era":"明治15年頃／昭和前期改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造、瓦葺、総延長18m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"27-712","desc":"本殿と拝殿及び幣殿を画す。東に三間、西に折曲がり七間半とし、切妻造、本瓦葺。柱間は腰を羽目板、腰長押と内法長押間を透し連子窓とする。軒は一軒疎垂木で、妻面の拝みには梅鉢懸魚を吊る。丁寧な造作の透塀で境内景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011989"},{"id":"00011987","register_sub_id":"101","register_pk":"211158","name":"男神社拝殿及び幣殿","kana":"おのじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉南市男里三丁目1065","lat":34.359384,"lng":135.257636,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"27-710","desc":"市内北西部の金熊川右岸に位置する境内に東西棟で建つ。拝殿は桁行五間、梁間二間、入母屋造で、組物は舟肘木、妻飾は豕扠首とし、幣殿が続く中央間のみ虹梁を架け蟇股を置く。細部意匠は復古的で、建築家池田谷久吉の力量が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011987"},{"id":"00015045","register_sub_id":"101","register_pk":null,"name":"加支多神社神饌所","kana":"かしたじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市鶴原1965","lat":34.42616944,"lng":135.34228056,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積3.3㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0916","desc":"本殿の西に位置し、基壇上に東面して建つ一間社流造鉄板葺。身舎は角柱とし、飛貫を通して鼻先を現し、組物は舟肘木で妻飾は大瓶束、軒は一軒で吹寄垂木とし、正面に桟唐戸を開く。全体的に装飾少ないながらも丁寧なつくりの小社で、境内の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015045"},{"id":"00015044","register_sub_id":"101","register_pk":"529322","name":"加支多神社拝殿及び幣殿","kana":"かしたじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府泉佐野市鶴原1965","lat":34.42608056,"lng":135.34224722,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0915","desc":"境内中央に南面して建つ入母屋造平入本瓦葺の拝殿。南に入母屋造妻入向拝を付し、北に両下造幣殿を接続する。拝殿正面は向拝両脇に格子窓を開け、楣と桁間の小壁に舟肘木と長押を装飾的に貼付ける。内部は一室で格天井張。重厚な本瓦葺屋根が境内景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015044"},{"id":"00015043","register_sub_id":"101","register_pk":null,"name":"加支多神社本殿","kana":"かしたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府泉佐野市鶴原1965","lat":34.42618889,"lng":135.34236389,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積6.4㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0914","desc":"見出川河口左岸、熊野街道沿いに位置する神社本殿。基壇上に南面して建つ一間社流造檜皮葺（銅板仮葺）で三方に刎高欄付縁を廻らす。庇柱は虹梁形頭貫を用いず三斗組で丸桁と海老虹梁を受ける。全体に簡素で整然とした意匠の本殿で境内の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015043"},{"id":"00010201","register_sub_id":"101","register_pk":"198034","name":"カトリック豊中教会司祭館","kana":"かとりっくとよなかきょうかいしさいかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市本町6-196","lat":34.790037,"lng":135.466806,"geo_status":"db","era":"昭和14／昭和中期・平成11・平成15改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建一部地階付、瓦葺、建築面積124㎡","structure_material":"木造2階建一部地階付","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0598","desc":"聖堂及びヨゼフ館の西側に南北棟で建つ。木造二階建、切妻造桟瓦葺で、東面中央に切妻屋根の玄関ポーチを構え、南壁面に煙突を立てる。丸太を使用した出桁造の軒廻りなどの細部意匠は聖堂と同様で、聖堂とともに静謐な敷地内空間を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010201"},{"id":"00010200","register_sub_id":"101","register_pk":"198033","name":"カトリック豊中教会聖堂及びヨゼフ館","kana":"かとりっくとよなかきょうかいせいどうおよびよぜふかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市本町6-196","lat":34.790341,"lng":135.46698,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋一部2階建、瓦葺一部鉄板葺、建築面積355㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0597","desc":"主体部である聖堂と、棟を直交して接続するヨゼフ館からなる。聖堂は屋根を入母屋造として鐘塔に刎高欄を廻らし、また三廊式平面の内部では、丸太柱、格天井、祭壇上の折上天井、組物付祭台を採用するなど、和風意匠を積極的に取入れる。木造和風教会の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010200"},{"id":"00012762","register_sub_id":"101","register_pk":"367665","name":"鴉宮稲荷社（旧本殿）","kana":"からすのみやいなりしゃ（きゅうほんでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市此花区伝法二丁目1-1","lat":34.68708,"lng":135.45724194,"geo_status":"db","era":"天明元年（1781）／昭和5年頃・同42年頃移築","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"27 － 765","desc":"淀川下流部の南側にある境内東隅に建つ。高い切石積基壇上建つ南正面の一間社流造で、正側面に擬宝珠高欄付の切目縁を廻して脇障子を立てる。組物は三斗実肘木。中備の蟇股や妻飾の大瓶束笈形を躍動感のある彫刻で飾る。小社ながら豊かな細部意匠をもつ社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012762"},{"id":"00007083","register_sub_id":"101","register_pk":"108065","name":"鴉宮中門及び透塀","kana":"からすのみやちゅうもんおよびすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市此花区伝法2-1-1","lat":34.68736089,"lng":135.4548771,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門 木造、銅板葺、間口2.0m 塀 木造、スレート葺、延長30m","structure_material":"門 木造","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0458","desc":"拝殿後方の切石積基壇上に建ち、両側に延びる透塀により本殿を囲う。切妻造銅板葺の四脚門で、菱格子付の桟唐戸を開く。軒は一軒繁垂木で、屋根とともに、本殿と同様の直線的な構成とする。神明造本殿の正門に相応しい、端正なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007083"},{"id":"00007082","register_sub_id":"101","register_pk":"108064","name":"鴉宮拝殿","kana":"からすのみやはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市此花区伝法2-1-1","lat":34.68727362,"lng":135.45484376,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0457","desc":"境内の中央、本殿前に建ち、桁行７．３ｍ梁間５．５ｍ、切妻造銅板葺。組物は出組で、中備に彫刻付蟇股を配し、軒は二軒繁垂木。妻飾は、一手持出す三重虹梁形式で、下段を木鼻付の平三斗詰組とし、中段を雲龍彫刻で埋める。本殿と対照的に華やかな意匠の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007082"},{"id":"00007081","register_sub_id":"101","register_pk":"108063","name":"鴉宮本殿","kana":"からすのみやほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市此花区伝法2-1-1","lat":34.68741847,"lng":135.4548671,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.3㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0456","desc":"河岸に位置する境内の奥に建つ。桁行２．８ｍ梁間２．３ｍ、神明造、銅板葺。低い亀腹上に建ち、柱は総円柱で、妻柱の外側に棟持柱を立て、軒は直線で構成し、棟に千木と勝男木を載せる。小規模ながら、昭和初期の神明造本殿として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007081"},{"id":"00007391","register_sub_id":"101","register_pk":"108373","name":"感田神社神楽殿","kana":"かんだじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447205,"lng":135.358948,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0512","desc":"境内地の東方に東西棟で建つ。桁行３間梁間２間半の木造平屋建で、北・西・南面に擬宝珠高欄付の切目縁をまわす。入母屋造桟瓦葺。内部は一室で、格天井を張る。東面は中央半間に神棚を造る。神事の際に西面中央柱を取り外し、広く開放とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007391"},{"id":"00007394","register_sub_id":"101","register_pk":"108376","name":"感田神社齋館","kana":"かんだじんじゃさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市中1546-2","lat":34.447212,"lng":135.35910642,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0515","desc":"参集殿の東南に位置し、渡廊下で繋がる。東西棟の入母屋造桟瓦葺で、西面に落棟を付ける。八畳の座敷と三畳の前室を東西に配し、座敷は東面に北から物入と違棚、トコを並べ、南面に平書院をつくる。前室には丸形の下地窓を開ける。軽快な意匠感覚が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007394"},{"id":"00007393","register_sub_id":"101","register_pk":"108375","name":"感田神社参集殿","kana":"かんだじんじゃさんしゅうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府貝塚市中1546-2他","lat":34.44735628,"lng":135.35893676,"geo_status":"db","era":"明治15／大正13移築","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0514","desc":"境内地の北辺に建つ、東西に細長い建物。屋根は本瓦葺で、東半部を入母屋造、西半部を切妻造とし、中央東寄りに入母屋造の式台を設ける。東端にはトコと違棚、平書院を構える十二畳半、その西に同規模の次の間を置き、縁をまわす。上質なつくりになる座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007393"},{"id":"00007392","register_sub_id":"101","register_pk":"108374","name":"感田神社神馬舎","kana":"かんだじんじゃしんめしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447048,"lng":135.358688,"geo_status":"db","era":"宝暦8","year":1758,"year_source":"db","year_min":1758,"year_max":1758,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.3㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0513","desc":"境内地の南辺、南門の東に建つ。桁行２．６ｍ梁間１．５ｍの木造平屋建。切妻造妻入桟瓦葺で、緩い起りをつける。方柱を建て、桁や梁を支持する。背面板壁で、他は腰竪格子とし、平側は上部に菱格子などを組む。木造神馬を安置し、伝統的な社頭景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007392"},{"id":"00007395","register_sub_id":"101","register_pk":"108377","name":"感田神社神門","kana":"かんだじんじゃしんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447502,"lng":135.358459,"geo_status":"db","era":"安永9","year":1780,"year_source":"db","year_min":1780,"year_max":1780,"year_label":null,"structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0516","desc":"南北の通りから少し東に入った位置に建つ。三間一戸二重門、入母屋造本瓦葺。初重は大斗肘木で、出桁造とし、一軒繁垂木。上重は平三斗で二軒扇垂木とする。初重両脇間には金剛柵と花頭窓を構え、上重には格狭間風に窓を開ける。独特な意匠構成になる神門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007395"},{"id":"00007396","register_sub_id":"101","register_pk":"108378","name":"感田神社土塀","kana":"かんだじんじゃどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.44759069,"lng":135.35819451,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土塀、瓦葺、延長20m","structure_material":"土塀","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0517","desc":"神門から通りまでの参道両脇と、神門南から三之社などの覆屋までの間に築かれる練塀。高さ２～２．５ｍ、折曲り総延長２０ｍを測る。屋根は切妻造瓦葺。白壁に仕上げるが、神門より内側は瓦と練り土が確認できる。神門とともに敷地正面に風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007396"},{"id":"00007386","register_sub_id":"101","register_pk":"108368","name":"感田神社末社一之社本殿","kana":"かんだじんじゃまっしゃいちのしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.44733,"lng":135.358536,"geo_status":"db","era":"安永2／昭和50改修","year":1773,"year_source":"db","year_min":1773,"year_max":1773,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0507","desc":"境内地中央に東面して建つ。桁行４．８ｍ梁間５．８ｍの木造平屋建で、その内部を方２．９ｍに画し、後半に壇を設け、三間社風に神殿を造る。神殿は正面に擬宝珠高欄付の木階と縁を設け、円柱で出組とし、二軒繁垂木。屋根は軒唐破風付檜皮葺。末社社殿の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007386"},{"id":"00007389","register_sub_id":"101","register_pk":"108371","name":"感田神社末社五之社本殿","kana":"かんだじんじゃまっしゃごのしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447392,"lng":135.358444,"geo_status":"db","era":"万延元","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.49㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0510","desc":"三之社本殿の西に位置する。小規模な一間社流造。三方に高欄付縁をまわし、正面に浜縁を付ける。身舎は円柱、大斗肘木、正面二軒繁垂木で、妻は虹梁大瓶束とする。屋根は葺足の粗い檜皮葺。向拝の彫刻が多少異なることを除けば、四之社本殿と同規模同形式。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007389"},{"id":"00007387","register_sub_id":"101","register_pk":"108369","name":"感田神社末社三之社本殿","kana":"かんだじんじゃまっしゃさんのしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447388,"lng":135.358459,"geo_status":"db","era":"万延元","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1.1㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0508","desc":"一之社の西北、三社を納める覆屋の中央に建つ。本瓦葺の一間社流造で、浜床・浜縁を付ける。柱は円柱で、三斗組とし、軒は一軒繁垂木。妻を虹梁大瓶束とする。身舎内部を前後に間仕切るが、中央に柱を建て、扉口を２ヶ所とする。丁寧なつくりになる社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007387"},{"id":"00007388","register_sub_id":"101","register_pk":"108370","name":"感田神社末社四之社本殿","kana":"かんだじんじゃまっしゃよんのしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447365,"lng":135.358475,"geo_status":"db","era":"万延元","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.49㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0509","desc":"三之社本殿の東に位置する。小規模な一間社流造。三方に高欄付縁をまわし、正面に浜縁を付ける。身舎は円柱、大斗肘木、正面二軒繁垂木とし、妻は虹梁大瓶束。屋根は葺足の粗い檜皮葺。向拝は連三斗組で、中備に松などの彫物を飾る。時代相応の細部意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007388"},{"id":"00007390","register_sub_id":"101","register_pk":"108372","name":"感田神社神輿蔵","kana":"かんだじんじゃみこしぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.4473,"lng":135.358505,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積21㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0511","desc":"一之社本殿の南側に東面して建つ。桁行４．９ｍ梁間４．２ｍの土蔵造平屋建。切妻造妻入本瓦葺。内部は一室で、中央の土間に神輿を置き、側・背面に低い板床を張る。外壁は腰板張とする白漆喰仕上げで、正面には銅板葺の唐破風を付け、印象的な意匠にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007390"},{"id":"00007397","register_sub_id":"101","register_pk":"108379","name":"感田神社南門","kana":"かんだじんじゃみなみもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.44709,"lng":135.358658,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造、瓦葺、間口4.1m、左右袖塀付","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0518","desc":"境内地南辺のほぼ中央に建つ。間口４．１ｍと規模の大きい、一間一戸高麗門。屋根は切妻造本瓦葺。切石上に五平柱を建て、楣で固める。肘木と斗で支えられた男梁が深く軒桁を持ち出す。軒は一軒疎垂木。脇の土塀とともに、敷地南面の街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007397"},{"id":"00005297","register_sub_id":"101","register_pk":"106285","name":"願得寺客間","kana":"がんとくじきゃくま","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府門真市御堂町8-23","lat":34.7426759,"lng":135.59635042,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0351","desc":"本堂と庫裏の間，玄関西に建つ。東西棟の切妻造，平屋建で，北に下屋を架け，桟瓦葺とする。平面は床付の６畳間を向かい合わせに配し，南に幅１間の広縁を設ける。控えの座敷だが，吟味した良材を多用し，洗練された床構えなど，近代の造形感覚が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005297"},{"id":"00005295","register_sub_id":"101","register_pk":"106283","name":"願得寺玄関","kana":"がんとくじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府門真市御堂町8-23","lat":34.74268228,"lng":135.59654842,"geo_status":"db","era":"宝暦2頃","year":1752,"year_source":"db","year_min":1752,"year_max":1752,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0349","desc":"南の本堂と北の庫裏の間に建つ。東を正面とし，式台付１０畳間の玄関と，その北の８畳の次の間からなり，西面に廊下が取り付く。玄関部は唐破風造，屋根は桟瓦葺である。本堂と庫裏を連結する機能を有し，玄関として格式のある外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005295"},{"id":"00005296","register_sub_id":"101","register_pk":"106284","name":"願得寺書院","kana":"がんとくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府門真市御堂町8-23","lat":34.74260304,"lng":135.5961729,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0350","desc":"本堂の西に建つ。東西棟の入母屋造で，四周に下屋を廻し，桟瓦葺とする。建ちが高く重層に見えるが，平屋建で内部空間を高くつくる。平面は床・棚・付書院のある書院と次の間を幅１間の畳敷広縁が囲む形式である。外観は簡素だが，瀟洒なつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005296"},{"id":"00005298","register_sub_id":"101","register_pk":"106286","name":"願得寺太鼓楼","kana":"がんとくじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府門真市御堂町8-23","lat":34.74283762,"lng":135.59670452,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋一部2階建、瓦葺、建築面積79㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0352","desc":"境内の東辺北半にある。南北棟で桟瓦葺の長大な長屋形式で，切石積基壇上に建ち，南寄に門口を設ける。北端に載る楼は真壁造で東西両面に花頭窓を設け，入母屋造，本瓦葺屋根とする。街路沿いの景観を整えるとともに，楼が真宗寺院らしい風格を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005298"},{"id":"00007238","register_sub_id":"101","register_pk":"108220","name":"源聖寺庫裏","kana":"げんしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-3-1","lat":34.66396142,"lng":135.51135842,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0467","desc":"松屋町筋東側に占める境内地の通り寄りに南面して建つ。南面入母屋造北面切妻造の本瓦葺で、大棟南寄りに切妻造の煙出を付ける。正面中央東寄りに庇を掛け、戸口とする。方柱で、柱上に舟肘木を載せ、妻は虹梁大瓶束。簡明ながら重厚な庫裏外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007238"},{"id":"00007239","register_sub_id":"101","register_pk":"108221","name":"源聖寺山門","kana":"げんしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-3-1","lat":34.66380376,"lng":135.51125386,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.2m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0468","desc":"松屋町筋に西面する一間薬医門。間口３．２ｍで、潜り付の袖塀を両脇に付ける。男梁上に三斗組を置き、虹梁及び桁を高くし、鏡天井を張る。妻は虹梁蟇股、軒は二軒繁垂木で、屋根は切妻造本瓦葺とする。大型の薬医門で、蟇股や虹梁など彫りの深い絵様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007239"},{"id":"00003114","register_sub_id":"101","register_pk":"104104","name":"源正寺楼門","kana":"げんしょうじろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町18-34","lat":34.629097,"lng":135.506973,"geo_status":"db","era":"明治22／大正12移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造楼門、瓦葺、建築面積13㎡","structure_material":"木造楼門","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0203","desc":"知恩院末で，鉄道敷設等により中央区上本町より現地に移築。初重袴腰を塗込める竜宮造の楼門で，上層は出組，二軒繁垂木，入母屋造，本瓦葺とする。蟇股や肘木の形式・絵様に近代らしい意匠が充溢するとともに，旧熊野街道に面し竜宮門として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003114"},{"id":"00015488","register_sub_id":"101","register_pk":"533503","name":"光聖寺山門","kana":"こうしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区生玉寺町3-4","lat":34.66150833,"lng":135.51445833,"geo_status":"db","era":"文政8年（1825）／昭和58年移築、令和6年改修","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造、金属板（チタン）葺、間口2.5m、総延長10m、袖塀付","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"27 - 0946","desc":"生玉寺町に位置する浄土宗寺院の山門。谷町筋に東面して建つ、一間一戸の薬医門で両脇に袖塀を延ばす。男梁鼻先に載せた大斗絵様肘木で軒桁を受け、軒は一軒繁垂木とする。妻飾は虹梁大瓶束笈形付。男梁、肘木、笈形などに精緻な彫刻を付し装飾華やかな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015488"},{"id":"00007242","register_sub_id":"101","register_pk":"108224","name":"光明寺庫裏","kana":"こうみょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-11","lat":34.662239,"lng":135.5114259,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0471","desc":"本堂の北側に玄関を介して繋がる。東西棟の切妻造本瓦葺で、大棟に煙出、妻面に下屋を設け、南面西寄りに庇を付け、出入口とする。壁は白漆喰仕上げ。玄関は入母屋造妻入桟瓦葺で、妻は木連格子。本堂と庫裏が並び建ち、重厚な境内景観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007242"},{"id":"00007243","register_sub_id":"101","register_pk":"108225","name":"光明寺山門","kana":"こうみょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-11","lat":34.66207576,"lng":135.5111199,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造、瓦葺、間口3.2m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0472","desc":"松屋町筋に西面する一間薬医門で、切妻造本瓦葺とする。間口３．２ｍで、潜戸付の袖塀を両脇に付ける。女梁を挿し肘木状に作り、男梁上に大斗肘木を組み、虹梁と軒桁を支持。妻は笈形付の虹梁大瓶束とし、軒は一軒繁垂木。鏡天井を張り、中備に龍の彫刻を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007243"},{"id":"00007241","register_sub_id":"101","register_pk":"108223","name":"光明寺本堂","kana":"こうみょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-11","lat":34.662045,"lng":135.51144255,"geo_status":"db","era":"宝永3","year":1706,"year_source":"db","year_min":1706,"year_max":1706,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積266㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0470","desc":"松屋町筋の東に占める境内地の中央に位置する。入母屋造本瓦葺で、正面に一間向拝を付ける。五間堂で中央に双折両開桟唐戸をたてる。外陣及び内陣、脇陣からなる典型的な浄土宗本堂平面をもつ。建具ほかに改変が見られるものの、江戸中期の形態を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007241"},{"id":"00001118","register_sub_id":"101","register_pk":"102108","name":"金光教玉水教会会堂","kana":"こんこうきょうたまみずきょうかいかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区江戸堀1-16-9","lat":34.69004964,"lng":135.49559738,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋一部二階建，銅板葺，建築面積531㎡","structure_material":"木造平屋一部二階建","registered":"1999.06.07(平成11.06.07)","register_no":"27 － 0059","desc":"木造平屋建、一部２階建とする裳階付きの大型の和風建物。入母屋造の大屋根平側に２つの千鳥破風をつけ賑やかに飾る。細部の意匠は全体的に伝統的な手法に則り構成される。堂々とした外観は、風格がある。設計は池田谷(久吉)建築事務所で、北井工務店が施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001118"},{"id":"00011765","register_sub_id":"101","register_pk":"210781","name":"金剛寺天野川東岸旧子院築地塀","kana":"こんごうじあまのがわとうがんきゅうしいんついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市天野町992他","lat":34.429323,"lng":135.529861,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土塀、瓦葺、総延長103m","structure_material":"土塀","registered":"2017.06.28(平成29.06.28)","register_no":"27-0701","desc":"天野川東岸の建物群を画す築地塀。川に面して建てられ、石垣基礎の上に、高さ〇・八メートルから一・三メートル程度の漆喰仕上の土壁を建て、上部に桟瓦を葺く。東岸にあった旧子院群の築地塀として設けられたもので、近世の境内状況を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011765"},{"id":"00011768","register_sub_id":"101","register_pk":"210784","name":"金剛寺大講堂","kana":"こんごうじだいこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市天野町992","lat":34.429346,"lng":135.530042,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積306㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0704","desc":"天野川の東岸、旧理趣院の敷地に建つ。寄棟造桟瓦葺の二重屋根、桁行一二間、梁間八間の規模で、正面中央には間口三間、切妻造の玄関を付す。小屋はトラス。天井が高く、縦長のガラス窓で明るい内部空間を実現する。近代の寺院における講堂の中でも大規模なもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011768"},{"id":"00011769","register_sub_id":"101","register_pk":"210785","name":"金剛寺大講堂食堂","kana":"こんごうじだいこうどうしょくどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市天野町992","lat":34.429598,"lng":135.530031,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積347㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0705","desc":"大講堂の北に建つ。前面側に九尺幅の廊下を通し、その背後に食堂部、炊事室部、書庫二室が並ぶ不整形平面で、食堂前に玄関を付す。屋根は桟瓦葺。食堂のみ格天井とし、他は棹縁天井。壁は真壁で腰下見板張とする。講堂と一連で建てられた、近代寺院施設の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011769"},{"id":"00011770","register_sub_id":"101","register_pk":"210786","name":"金剛寺鎮守橋","kana":"こんごうじちんじゅばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市天野町","lat":34.428514,"lng":135.530187,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造、銅板葺、全長6.4m","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"27-0706","desc":"天野川の境内入口付近にかかる木造橋。主伽藍と鎮守社を結ぶ。全長六・四メートル、幅三・〇メートルで、橋桁は僅かに反りを持つ。屋根は橋本体とは独立した柱で支持される切妻造銅板葺。本格的な構造を有する屋根を持つ橋で、寺院境内にふさわしい造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011770"},{"id":"00011760","register_sub_id":"101","register_pk":"210776","name":"金剛寺本坊奥殿","kana":"こんごうじほんぼうおくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府河内長野市天野町995","lat":34.429157,"lng":135.529596,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積284㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0696","desc":"桁行五間、梁間四間、入母屋造茅葺で、庇は桟瓦葺。一八畳間を中心に二列六間を配し、周囲には一間幅の畳縁を廻らす。南東隅には浴室などを収める附属屋が付く。御座の間を格天井とする以外は全て棹縁天井とする。大規模な御座所の遺例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011760"},{"id":"00011763","register_sub_id":"101","register_pk":"210779","name":"金剛寺本坊表門","kana":"こんごうじほんぼうおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.429729,"lng":135.529664,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"27-0699","desc":"子院群が統合された際に現位置に移築改修されたもの。北面する一間薬医門で、脇に築地塀が取り付く。切妻造本瓦葺で、五平の親柱に冠木を渡し、上下から男梁女梁で固める。軒は一軒繁垂木。全体に木柄が太く、大玄関と併せて本坊の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011763"},{"id":"00011758","register_sub_id":"101","register_pk":"210774","name":"金剛寺本坊客殿","kana":"こんごうじほんぼうきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.429654,"lng":135.529505,"geo_status":"db","era":"江戸中期／平成3年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0694","desc":"中院の庫裏であったもの。桁行六間、梁間三間半、東面し、周囲には広縁を廻らす。屋根は入母屋造本瓦葺。平面は二列構成で、表側は八畳間三室を連ね、背面側は一間幅とする。天井は棹縁天井とし、部屋境は筬欄間とする。庭園に面し、境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011758"},{"id":"00011757","register_sub_id":"101","register_pk":"210773","name":"金剛寺本坊持仏堂","kana":"こんごうじほんぼうじぶつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.42881111,"lng":135.52938611,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0693","desc":"金剛寺の子院であった中院の持仏堂で、現在は金剛寺本坊の回遊式庭園の一端をなす。三間四方で東面し、背面に仏壇を張り出す。屋根は宝形造銅板葺。面取角柱に舟肘木をのせ、一軒疎垂木とする。内部は一室。近世期金剛寺の子院に建てられた、持仏堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011757"},{"id":"00011759","register_sub_id":"101","register_pk":"210775","name":"金剛寺本坊大玄関","kana":"こんごうじほんぼうだいげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.429449,"lng":135.529641,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺一部檜皮葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0695","desc":"旧子院群の統合に際し建てられた。入母屋造、本瓦葺の主体部に六畳・八畳・六畳を配し、その前面に檜皮葺の式台玄関を付す。玄関西脇には茶室を設ける。南・西には濡縁を廻らし、南縁は海老虹梁をかけ、化粧木舞裏とする。本坊正面の重厚な構えを作る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011759"},{"id":"00011762","register_sub_id":"101","register_pk":"210778","name":"金剛寺本坊茶室","kana":"こんごうじほんぼうちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.429566,"lng":135.529287,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0698","desc":"持仏堂の背後に建つ。入母屋造銅板葺で、四畳半茶室の北に水屋が付属する。茶室は、北東隅の二面に下地窓を設け、南面に貴人口、西面南端に躙口を配す。天井は、西寄りを掛込、他は棹縁天井とする。東端部を懸造状で造る、質の高い茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011762"},{"id":"00011761","register_sub_id":"101","register_pk":"210777","name":"金剛寺本坊渡廊下","kana":"こんごうじほんぼうわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府河内長野市天野町995","lat":34.429325,"lng":135.529659,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、檜皮葺一部茅葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0697","desc":"大玄関と奥殿をつなぐ渡廊下。一間幅の両下造檜皮葺で、中程に一間半四方、宝形造茅葺の四阿を設ける。軸部に丸太材や竹材を中心に用い、外板壁内土壁とする腰壁を配し、床は磚の四半敷。全体に草庵風の趣を見せ、庭園と併せて境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011761"},{"id":"00011764","register_sub_id":"101","register_pk":"210780","name":"金剛寺無量寿院・籠堂","kana":"こんごうじむりょうじゅいん・こもりどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天野町1539","lat":34.429144,"lng":135.530092,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0700","desc":"入母屋造桟瓦葺の主体部に向唐破風造の式台玄関が取り付く無量寿院部分と、北半の切妻造桟瓦葺、妻入の籠堂からなる。籠堂の妻面は二重虹梁大瓶束で古式とするが、その他はガラス建具を多用するなど近代的な意匠でまとめる。様々な時代性を備える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011764"},{"id":"00010193","register_sub_id":"101","register_pk":"198026","name":"西教寺大門及び築地塀","kana":"さいきょうじおおもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501228,"lng":135.438931,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"大門 木造、瓦葺、間口2.4m 築地塀 土塀、瓦葺、総延長12m","structure_material":"大門 木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0590","desc":"境内正面の薬医門形式の大門と左右に伸びる築地塀。大門は妻虹梁上の大瓶束に雲紋の笈形を付し、棟虹梁上の束の笈形には対の龍を象るなど、力強い造形をみせる。築地塀は壁面に定規筋二本をいれ、端部の貝形に絵様虹梁と蟇股を飾る。境内表構えに風格を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010193"},{"id":"00010191","register_sub_id":"101","register_pk":"198024","name":"西教寺上書院","kana":"さいきょうじかみしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-252","lat":34.501476,"lng":135.438568,"geo_status":"db","era":"明治中期／昭和期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0588","desc":"本堂後方に建つ、二階建、寄棟造桟瓦葺の書院で、本堂から二階へ廊下がのびる。上下階とも八畳二室と縁からなるが、二階の奥室が格式が高く、上段の間として座敷飾りを備える。二階次の間には、トコに火灯窓を穿つ。貴人の接遇用に整えられた書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010191"},{"id":"00010199","register_sub_id":"101","register_pk":"198032","name":"西教寺北門","kana":"さいきょうじきたもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501311,"lng":135.438944,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0596","desc":"境内北辺東寄り、太鼓楼と経蔵の間に建つ一間薬医門で、間口二・一メートル、切妻造本瓦葺である。五平の本柱の頂部に冠木を渡し、矩形の梁を三筋架け、鼻先の桁で垂木を受ける。太鼓楼や経蔵、本堂の屋根とともに、境内北面の街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010199"},{"id":"00010196","register_sub_id":"101","register_pk":"198029","name":"西教寺経蔵","kana":"さいきょうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501342,"lng":135.438896,"geo_status":"db","era":"明治24頃","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積6.1㎡","structure_material":"土蔵造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0593","desc":"本堂前庭の北寄りに建つ。正方形平面をもつ土蔵造平屋建の経蔵で、宝形造本瓦葺とし、宝珠を載せる。外部は漆喰塗で、板軒状の軒まで塗込め、柱や長押のほか舟肘木や蟇股などの細部も漆喰で表す。内部は素木で経棚を設える。堅実な左官仕上げになる経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010196"},{"id":"00010190","register_sub_id":"101","register_pk":"198023","name":"西教寺式台玄関及び書院","kana":"さいきょうじしきだいげんかんおよびしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501278,"lng":135.438651,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0587","desc":"本堂左手に接続する入母屋造本瓦葺の建物で、正面に式台を構える。式台の後方を六畳の玄関とし、四畳を介して八畳と六畳からなる書院を配し、縁を廻らせる。式台は正面内法に筬欄間をたて、虹梁絵様や蟇股を波紋や雲紋として飾り、格天井を張り、風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010190"},{"id":"00010195","register_sub_id":"101","register_pk":"198028","name":"西教寺鐘楼","kana":"さいきょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501178,"lng":135.438888,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造、瓦葺、面積5.5㎡","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0592","desc":"境内正面、東門と大門の間に位置する吹放し形式の鐘楼で、切妻造本瓦葺である。切石布積の高い基壇上に建ち、円柱を貫と台輪で固め、組物三斗で中備に彫刻化した蟇股をおき、妻虹梁上の大瓶束に華やかな笈形を付ける。建ちが高く境内の正面景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010195"},{"id":"00010197","register_sub_id":"101","register_pk":"198030","name":"西教寺太鼓楼","kana":"さいきょうじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501294,"lng":135.438972,"geo_status":"db","era":"昭和37","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造2階建、瓦葺、建築面積14㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0594","desc":"境内北東隅に建つ二階建の太鼓楼。木造モルタル塗、入母屋造本瓦葺で、一階西面を出入口とし、二階は四面に黒枠の火灯窓を穿ち、アクセントとする。外壁漆喰塗で二階に長押を表し、軒は板軒状に仕上げる。角地にあって真宗寺院の伽藍景観を特徴付ける太鼓楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010197"},{"id":"00010192","register_sub_id":"101","register_pk":"198025","name":"西教寺手水屋","kana":"さいきょうじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501219,"lng":135.438825,"geo_status":"db","era":"文化13頃","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造、瓦葺、面積4.6㎡","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0589","desc":"本堂南東側の前庭に建ち、切妻造本瓦葺である。角柱四本を内転びに建て、中央に手水鉢を置き、四方吹放しとする。柱上に舟肘木を輪薙込に組んで桁と妻虹梁を受け、虹梁上に間斗束を立て、棟通りには蟇股を飾る。小規模ながら建築的細部を丁寧に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010192"},{"id":"00010198","register_sub_id":"101","register_pk":"198031","name":"西教寺東門","kana":"さいきょうじひがしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501099,"lng":135.438834,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0595","desc":"境内東辺南端、鐘楼の隣に構える門で、本堂脇の式台玄関への入口にあたる。一間薬医門、間口二・二メートル、切妻造本瓦葺で、左右に築地塀が接続する。本柱は五平材で、男梁を三筋架け、大斗実肘木で桁と梁を受ける。日常の使用に供される通用門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010198"},{"id":"00010189","register_sub_id":"101","register_pk":"198022","name":"西教寺本堂","kana":"さいきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501373,"lng":135.438714,"geo_status":"db","era":"文化5／大正頃改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0586","desc":"間口一五メートルの真宗寺院本堂で、背面に茶室及び奥座敷を付属する。内陣と左右の余間を上段とし、須弥壇の背面に後門を開く。外陣は左右に長い一室で前面柱間が広く、内部柱を省く。内陣や内外陣境を彫刻や極彩色で華やかに荘厳し、時代的特色をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010189"},{"id":"00010194","register_sub_id":"101","register_pk":"198027","name":"西教寺門柱及び鉄柵","kana":"さいきょうじもんちゅうおよびてつさく","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.50120195,"lng":135.43897031,"geo_status":"db","era":"明治31／昭和中期改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"門柱 石造、間口2.4m、鉄扉付 鉄柵 総延長6.3m","structure_material":"門柱 石造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0591","desc":"大門正面に構える一対の門柱と鉄柵。門柱は花崗岩製で頂部を宝形に加工し、柱間に、上辺をアーチ状とした鉄製門扉を両開きに吊る。門柱と両端の石柱との間には鉄柵を設け、鏃を付けた長短二種の縦格子を交互に立てる。大門とともに、境内入口の結界を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010194"},{"id":"00005293","register_sub_id":"101","register_pk":"106281","name":"慈願寺表門及び築地塀","kana":"じがんじおもてもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.62690212,"lng":135.59790209,"geo_status":"db","era":"安政3","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"表門 木造、瓦葺、間口3.7m、築地塀 土塀、瓦葺、延長12m","structure_material":"表門 木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0347","desc":"境内正面の東辺中央にある。表門は１間薬医門形式で，軒は二軒繁垂木とし，切妻造，本瓦葺屋根を架ける。腕木は端部を木鼻状につくり，大斗絵様肘木を受ける。表門の両側には，Ｌ字型平面で本瓦葺屋根の築地塀が延び，重厚な正面景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005293"},{"id":"00005291","register_sub_id":"101","register_pk":"106279","name":"慈願寺経蔵","kana":"じがんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.6270069,"lng":135.59764576,"geo_status":"db","era":"明治9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積32㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0345","desc":"本堂の北東にある。桁行４．８ｍの寄棟造，平入で，正面の東面に唐破風造の１間向拝を設け，屋根は本瓦葺とする。外壁は漆喰塗で軒裏まで塗籠め，腰を横板で覆う。向拝の虹梁絵様や中備蟇股などの細部には，江戸末期の造形が継承されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005291"},{"id":"00005292","register_sub_id":"101","register_pk":"106280","name":"慈願寺鐘楼","kana":"じがんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.6267833,"lng":135.59786214,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造、瓦葺、面積29㎡","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0346","desc":"表門南方にあり，切石積基壇上に建つ。桁行１間，梁間１間，四方吹放し形式で，南北棟で切妻造，本瓦葺屋根を架ける。円柱を内転びに立て，三斗を組む。妻飾の虹梁大瓶束に棟方向の虹梁を組み込み，これに鐘を吊る。架構や細部が巧みで，丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005292"},{"id":"00005290","register_sub_id":"101","register_pk":"106278","name":"慈願寺太鼓楼","kana":"じがんじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.62697769,"lng":135.59788738,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積38㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0344","desc":"西を正面とし，南北棟の入母屋造で平屋建の北寄りに，入母屋造の２階を載せた形式で，軒は上下とも一軒，屋根は本瓦葺である。２階は真壁造で，各面とも中央間に花頭窓を設ける。境内東の入口，表門北側の築地塀沿いにあり，街路景観上，際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005290"},{"id":"00005289","register_sub_id":"101","register_pk":"106277","name":"慈願寺手水屋","kana":"じがんじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.62697052,"lng":135.59781614,"geo_status":"db","era":"寛文年間","year":1667,"year_source":"estimated","year_min":1661,"year_max":1673,"year_label":"寛文年間","structure":"木造、瓦葺、面積12㎡","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0343","desc":"境内の東側入口にある。桁行１間，梁間１間，四方吹放し形式で，東西棟の切妻造，本瓦葺屋根を架ける。面取角柱を内転びに立てて虹梁型頭貫で固め，大斗肘木を載せ，妻は虹梁と笈形付の蓑束で飾る。虹梁や木鼻の絵様細部等から，寛文年間のものと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005289"},{"id":"00005288","register_sub_id":"101","register_pk":"106276","name":"慈願寺本堂","kana":"じがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.626896,"lng":135.597412,"geo_status":"db","era":"文化14","year":1817,"year_source":"db","year_min":1817,"year_max":1817,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積561㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0342","desc":"入母屋造，平入，向拝１間，本瓦葺で，東面して建つ。平面は真宗本堂らしく，外陣，矢来，内陣と続き，内陣左右に余間と飛檐の間を配し，外陣の三方には吹放しの広縁を廻す。桁行１９ｍと雄大な規模を有し，架構から組物及び細部まで，充実したつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005288"},{"id":"00005294","register_sub_id":"101","register_pk":"106282","name":"慈願寺脇門及び築地塀","kana":"じがんじわきもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.62675538,"lng":135.5979393,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"脇門 木造、瓦葺、間口3.1m、築地塀 土塀、瓦葺、延長12m","structure_material":"脇門 木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0348","desc":"脇門は境内東南方に東面して建つ。１間棟門形式で，前後に控柱を立て，軒を二軒繁垂木とし，切妻造，本瓦葺屋根を架ける。本瓦葺屋根の築地塀は脇門から北に延び，表門南側の築地塀に接続する。表門などとともに，風格のある街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005294"},{"id":"00014651","register_sub_id":"101","register_pk":"515193","name":"地蔵寺庫裏","kana":"じぞうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府河内長野市清水111-甲他","lat":34.40833333,"lng":135.58488889,"geo_status":"db","era":"昭和13年／同50年代改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0895","desc":"景勝地の真言宗寺院山門脇にある庫裏。切妻造平入桟瓦葺、妻壁に木瓜形窓を見せる。入母屋造式台玄関を構え、虹梁蟇股にホトトギスを彫る。内部は縁を巡らした六間取座敷と元土間の台所からなる。均整の取れた大屋根が奥行きある参道の境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014651"},{"id":"00014652","register_sub_id":"101","register_pk":"515194","name":"地蔵寺山門","kana":"じぞうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府河内長野市清水111-甲他","lat":34.40823889,"lng":135.585125,"geo_status":"db","era":"明治35年／令和2年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0896","desc":"真言宗寺院の表構えとなる一間一戸薬医門。石段を登った先を花崗岩切石敷とする。切妻造桟瓦葺、軒は疎垂木で裏板流板張。男梁に板蟇股を載せ、女梁は絵様繰形付で、八双金具付板扉を吊る。全体に端正な造りで、境内の落ち着きある歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014652"},{"id":"00014650","register_sub_id":"101","register_pk":"515192","name":"地蔵寺鍾馗堂","kana":"じぞうじしょうきどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市清水111-甲他","lat":34.40834722,"lng":135.58454722,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0894","desc":"真言宗寺院本堂北側に接続する仏堂で、鍾馗印の藤澤友吉商店が寄進。入母屋造妻入桟瓦葺。正面濡縁付、脇間に火灯窓を構える。内部は三間四方格天井畳敷、奥に仏壇を設ける。亀腹はコンクリート造。境内に瓦葺屋根を連ねて景勝地の歴史的景観となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014650"},{"id":"00014649","register_sub_id":"101","register_pk":"515191","name":"地蔵寺本堂","kana":"じぞうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市清水111-甲他","lat":34.40822222,"lng":135.58456944,"geo_status":"db","era":"享保6年（1721）／昭和3年改修","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0893","desc":"ホトトギスの名勝で知られる真言宗寺院の本堂。宝形造桟瓦葺、元は茅葺。一軒繁垂木、柱上に絵様肘木を置く。内部は円柱を立てた中央間を折上格天井の板敷とし、背面奥に須弥壇を置く。須弥壇前に天女の板絵を吊し、他に雲形の板も伝わり荘厳に特徴有る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014649"},{"id":"00014260","register_sub_id":"101","register_pk":"509650","name":"四天王寺阿弥陀堂","kana":"してんのうじあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65318889,"lng":135.51570833,"geo_status":"db","era":"延宝2年（1674）／昭和28年・昭和63年移築","year":1674,"year_source":"db","year_min":1674,"year_max":1674,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積135㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0851","desc":"寺域南西部に北面して建つ希少な寄棟造妻入の仏堂。本瓦葺、二軒繁垂木、出組、中備正面蟇股、側面間斗束、東西五間、南北六間と奥深く、化粧屋根裏と鏡天井の外陣・格天井の内陣・後陣からなる平面構成。三重県国束寺本堂を移築した紀州徳川家ゆかりの建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014260"},{"id":"00014259","register_sub_id":"101","register_pk":"509649","name":"四天王寺廻廊","kana":"してんのうじかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65378611,"lng":135.516825,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積1116㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0850","desc":"詳細な発掘調査により、鉄骨鉄筋コンクリート造で復元した単廊と門。単廊は位置・規模は創建から変わらず、一軒隅扇垂木、小屋組は虹梁に豕扠首とする。東・西重門は三間門切妻造で小壁に人字形割束を置く。発掘成果に基づき古代寺院の姿を復元した初例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014259"},{"id":"00014257","register_sub_id":"101","register_pk":"509647","name":"四天王寺講堂","kana":"してんのうじこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65424722,"lng":135.51642778,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積317㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0848","desc":"金堂後方に位置する鉄骨鉄筋コンクリート造による復元講堂。一重、入母屋造錣葺。東西規模、丸太材による隅扇垂木、風鐸は発掘成果に基づく。金堂に比べて柱が細く、胴張弱いのは初唐様式を参考に差別化した。発掘成果に基づき古代寺院の姿を復元した初例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014257"},{"id":"00014255","register_sub_id":"101","register_pk":"509645","name":"四天王寺五重塔","kana":"してんのうじごじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65360278,"lng":135.516475,"geo_status":"db","era":"昭和34年／令和元年補強","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄骨鉄筋コンクリート造五重塔、瓦葺、建築面積56㎡","structure_material":"鉄骨鉄筋コンクリート造五重塔","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0846","desc":"伽藍中心に位置する鉄骨鉄筋コンクリート造の五重塔。塔高約三七メートル、外観は法隆寺五重塔に倣い飛鳥様式を基本に、より古い形態とするが、内部は六層でらせん階段を配する。発掘成果に基づき古代寺院の姿を復元した初例で、藤島亥治郎の設計による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014255"},{"id":"00014256","register_sub_id":"101","register_pk":"509646","name":"四天王寺金堂","kana":"してんのうじこんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65387222,"lng":135.51645,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積231㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0847","desc":"詳細な発掘調査に基づき創建位置に鉄骨鉄筋コンクリート造で復元した金堂。二重、入母屋造錣葺。高さは法隆寺の塔と金堂の関係に倣い、外観は法隆寺金堂を基本とし、より大陸的で直線的な構成とした。発掘成果に基づき古代寺院の姿を復元した初例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014256"},{"id":"00014262","register_sub_id":"101","register_pk":"509652","name":"四天王寺聖霊院唐門","kana":"してんのうじしょうりょういんからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65297778,"lng":135.51715,"geo_status":"db","era":"文化5年（1808）／明治30年頃・昭和27年移築・同54年頃改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.6㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0853","desc":"寺域南東部に南面して建つ四脚門。切妻造で軒唐破風付、銅板葺は元は檜皮葺で、二軒繁垂木とする。桟唐戸、礎盤、粽柱など禅宗様の意匠と、蟇股等の精巧な彫刻で格式高く飾る。徳川家康を合祀した用明殿の正門として建築、本坊御成門を経て、現在地に至る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014262"},{"id":"00014264","register_sub_id":"101","register_pk":"509654","name":"四天王寺青龍亭","kana":"してんのうじせいりゅうてい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65589444,"lng":135.51808889,"geo_status":"db","era":"明治後期／平成15年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0855","desc":"四天王寺本坊の庭園内に建つ独立した茶室。木造平家建、屋根は銅板葺で元は杉皮葺。内部は台形と正三角形の二席と、これらを繋ぐ水屋からなる斬新な平面で、各部意匠は侘びた風情を醸す草庵風だが、一方で開口部が大きくて明るく近代的な茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014264"},{"id":"00014258","register_sub_id":"101","register_pk":"509648","name":"四天王寺中門","kana":"してんのうじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65335833,"lng":135.51648056,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積86㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0849","desc":"詳細な発掘調査に基づき、創建位置に鉄骨鉄筋コンクリート造で復元した中門。三間一戸八脚門、入母屋造錣葺。一軒隅扇垂木、雲斗など全体に意匠は飛鳥様式とする。上部構造は塔や南大門との関係から単層とした。発掘成果に基づき古代寺院の姿を復元した初例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014258"},{"id":"00014261","register_sub_id":"101","register_pk":"509651","name":"四天王寺納骨堂","kana":"してんのうじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65317222,"lng":135.51558056,"geo_status":"db","era":"江戸中期／昭和28年・昭和63年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0852","desc":"寺域南西部に北面して建つ方三間仏堂。宝形造桟瓦葺、一軒疎垂木、平三斗組、中備正面中央蟇股それ以外蓑束。角柱で上端に粽を付け、肘木は笹繰付。内部は格天井で、奥側三面に納骨壇、その中央に軒唐破風の宮殿を置く。三重県国束寺聖天堂を移築したもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014261"},{"id":"00014263","register_sub_id":"101","register_pk":"509653","name":"四天王寺本坊唐門","kana":"してんのうじほんぼうからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65486111,"lng":135.51708333,"geo_status":"db","era":"江戸後期／天保頃改修・明治30年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積6.2㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0854","desc":"寺域北東部の本坊の南西に建つ正門。向唐門本瓦葺で元檜皮葺、格天井とし、桟唐戸、礎盤、粽柱など禅宗様を基調とする。徳川歴代将軍の霊牌を祀る五智光院の正門として建築、虹梁上の霊廟守護の雲竜彫刻、扉の三つ葉葵紋透彫り、錺金具を施すなど格式高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014263"},{"id":"00007237","register_sub_id":"101","register_pk":"108219","name":"稱念寺山門","kana":"しょうねんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-5-1","lat":34.66506362,"lng":135.51133872,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0466","desc":"松屋町筋に西面して建つ一間薬医門。間口２．９ｍ幅に本柱を建て、女梁、冠木、男梁を架し、妻及び中備には蟇股を置く。一軒疎垂木で、屋根を切妻造本瓦葺とする。装飾を抑えるが、木鼻など細部に、江戸中期らしい意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007237"},{"id":"00007247","register_sub_id":"101","register_pk":"108229","name":"稱名寺山門","kana":"しょうみょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町2-14","lat":34.659035,"lng":135.5108728,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0476","desc":"松屋町筋に西面する一間高麗門。間口２．８ｍで、腰海鼠壁とする袖塀を両脇に付ける。妻蟇股とし、軒は一軒繁垂木。切妻造本瓦葺で、棟には龍の飾り瓦、隅蓋瓦に波紋を飾る。小規模ながら、たちの高い高麗門で、薬医門が並ぶ下寺町において印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007247"},{"id":"00014634","register_sub_id":"101","register_pk":"515176","name":"真行寺本堂","kana":"しんぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目39","lat":34.67075,"lng":135.56044167,"geo_status":"db","era":"天保3年（1832）／昭和33年・平成16年頃改修","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0878","desc":"旧深江村の集落北寄りにある真宗寺院の本堂。入母屋造平入本瓦葺、正面五間、向拝付、奥行の三間半を外陣及び脇間、框を入れて奥を一段高く内陣と左右余間とし、須弥壇背面に後門を開く。内外陣境を彫刻欄間と菱格子欄間で荘厳する。集落の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014634"},{"id":"00007244","register_sub_id":"101","register_pk":"108226","name":"心光寺山門","kana":"しんこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-7","lat":34.66169,"lng":135.511047,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0473","desc":"松屋町筋に西面する一間薬医門で、切妻造本瓦葺とする。間口２．７ｍ幅に本柱を建て、女梁と男梁、冠木を架し、男梁上に大斗を載せ、虹梁と軒桁を支持する。妻は虹梁大瓶束。大瓶束の上方には木鼻を四方に出す。男梁鼻先や虹梁絵様などの細部意匠は秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007244"},{"id":"00003565","register_sub_id":"101","register_pk":"104555","name":"心光寺本堂","kana":"しんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-3-68","lat":34.661678,"lng":135.51152,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積228㎡、ドーム付","structure_material":"鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"27 － 0258","desc":"市内を南北に貫通する松屋町筋東方の寺町に位置する。火災後の再建になる鉄筋コンクリート造寺院で，住職の設計と伝える。ドーム屋根，柱上の相輪風の飾り，パラペットの宝珠柱風手摺子，多弁アーチなどによりインド風の外観を造りだす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003565"},{"id":"00011353","register_sub_id":"101","register_pk":"209190","name":"真宗大谷派茨木別院鐘楼","kana":"しんしゅうおおたにはいばらきべついんしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府茨木市別院町3-31","lat":34.816896,"lng":135.574227,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、面積8.8㎡","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"27－0651","desc":"本堂南東側に位置し、花崗岩を精緻に積む基壇上に南北棟で建つ吹放ち形式の鐘楼で切妻造本瓦葺。軸部は石製礎盤に几帳面取角柱を立て、三斗を組む。妻飾は虹梁蟇股で、大梁端部が蟇股を貫いて波紋の木鼻となる独特な造形をもつ。街路からの景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011353"},{"id":"00011351","register_sub_id":"101","register_pk":"209188","name":"真宗大谷派茨木別院本堂","kana":"しんしゅうおおたにはいばらきべついんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府茨木市別院町3-31","lat":34.817042,"lng":135.573818,"geo_status":"db","era":"安永6","year":1777,"year_source":"db","year_min":1777,"year_max":1777,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積778㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0649","desc":"市街地の境内に東面し、桁行三〇メートルを測る大堂。後門形式の平面など真宗寺院本堂の典型を示す一方、矢来内を外陣より一段高め、余間まわりを円柱とするなど高い寺格も表している。力感ある軸部、壮大な内部、優れた意匠に工匠の高い力量が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011351"},{"id":"00002060","register_sub_id":"101","register_pk":"103050","name":"少彦名神社拝殿","kana":"すくなひこなじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区道修町2-1-8","lat":34.68875017,"lng":135.50598893,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0121","desc":"桁行３間，梁間２間，入母屋造，銅板葺で，正面に千鳥破風，軒唐破風を付ける。中央１間通りはもと土間で割拝殿形式であった。全体に簡素な造りだが正面は装飾的な構えとなり，虹梁上に太瓶束を立て菖蒲桁を受ける唐破風の構成など，巧みな処理が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002060"},{"id":"00002059","register_sub_id":"101","register_pk":"103049","name":"少彦名神社幣殿","kana":"すくなひこなじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区道修町2-1-8","lat":34.68879141,"lng":135.50599845,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0120","desc":"正面一間，側面二間，両下造，銅板葺で，本殿正面に取り付く。角柱に虹梁形頭貫を通し台輪を載せ，絵様肘木及び中備の蟇股を置いて桁を受け，正面では笈形付太瓶束を立て棟木を支える。本殿と対照的に彫刻を多用した建物で，一体となって特徴ある構成を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002059"},{"id":"00002058","register_sub_id":"101","register_pk":"103048","name":"少彦名神社本殿","kana":"すくなひこなじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区道修町2-1-8","lat":34.68881993,"lng":135.50600083,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0119","desc":"道修町は江戸時代以来，薬問屋が集中する地で，当社は薬の神である少彦名命を祀る。本殿は桁行一間，梁間二間，切妻造，銅板葺，平入りの小規模な社殿で，妻梁を虹梁形に造るほか装飾のない簡素な造りだが，全体の比例が良く，良材による質の高い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002058"},{"id":"00012422","register_sub_id":"101","register_pk":"531746","name":"住吉大社角鳥居","kana":"すみよしたいしゃかくとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61248333,"lng":135.49255556,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、間口4.0m、高さ4.1m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-748","desc":"本宮域の幸寿門前に立つ。石造で、柱に大面取の角柱を用いるが、貫を通し、反りのある島木･笠木を重ねるなど明神鳥居の形式とする。重心の低いどっしりとした造形で境内の他の鳥居と一線を画する。同社を代表する鳥居として古くから参拝者に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012422"},{"id":"00012405","register_sub_id":"101","register_pk":"531729","name":"住吉大社北絵馬殿","kana":"すみよしたいしゃきたえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61265,"lng":135.4919,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-731","desc":"神池にかけられた反橋手前の表参道北側に建つ。桁行三間梁間一間、東西棟の切妻造本瓦葺で、規模･形式とも南絵馬殿と寸分違わない。用途上の使い分けもなく二棟一対で絵馬殿として機能する。反橋と調和し、同社を象徴する社頭景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012405"},{"id":"00012421","register_sub_id":"101","register_pk":"531745","name":"住吉大社北大鳥居","kana":"すみよしたいしゃきたおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61333333,"lng":135.49225833,"geo_status":"db","era":"江戸前期／明治前期移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、間口5.7m、高さ6.5m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-747","desc":"境内側面の北からの参道入口に立つ。石造で、西鳥居と同じ形式の明神鳥居であるが、規模は一回り小さくつくる。東と南の大鳥居とは同規模で、四基一対で四至を結界する。境内の四方を固める主要な入口の一つとして、広大な境内の北面の構えの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012421"},{"id":"00012414","register_sub_id":"101","register_pk":"531738","name":"住吉大社北瑞籬門","kana":"すみよしたいしゃきたみずがきもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61256389,"lng":135.49364722,"geo_status":"db","era":"江戸後期／昭和38年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、銅板葺、間口4.4m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-740","desc":"本宮域の背面北端にある切妻造銅板葺の四脚門。規模･形式とも南端籬門と寸分違わず、本宮域の背後を固める左右一対の門としてつくられる。南端籬門と同じく、第一殿の脇に建ち、境内中心部の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012414"},{"id":"00012424","register_sub_id":"101","register_pk":"531748","name":"住吉大社北脇参道角鳥居","kana":"すみよしたいしゃきたわきさんどうかくとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61328889,"lng":135.4917,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造、間口4.6m、高さ5.0m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-750","desc":"北脇参道の入口に立つ。柱を大面取の角柱とした石造の明神鳥居で、幸寿門前の角鳥居の形式に準ずるが、均整のとれた造形と均質な仕上が時代感覚を伝える。南脇参道角鳥居と左右一対で中央の西大鳥居の脇を固める、同社の境内正面の構成に不可欠な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012424"},{"id":"00012411","register_sub_id":"101","register_pk":"531735","name":"住吉大社幸寿門","kana":"すみよしたいしゃこうじゅもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61246111,"lng":135.49263333,"geo_status":"db","era":"江戸前期／昭和45年移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、銅板葺、間口4.6m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-737","desc":"本宮域の正面中央にある切妻造銅板葺の四脚門。組物は実肘木付の三斗、妻飾は虹梁蟇股、破風に梅鉢懸魚を吊る。門扉の上は冠木と棟木の間に虹梁を入れ、その下に蟇股、上に大瓶束を備えた独特の構成とするなど、本宮域の表構えとしての格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012411"},{"id":"00012412","register_sub_id":"101","register_pk":"531736","name":"住吉大社幸福門","kana":"すみよしたいしゃこうふくもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61223889,"lng":135.4926,"geo_status":"db","era":"江戸前期／昭和45年移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、銅板葺、間口4.5m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-738","desc":"本宮域の正面脇にある切妻造銅板葺の四脚門。幸寿門と同じ規模･形式であるが、組物を大斗肘木とし、冠木と棟木の間は中備の蓑束のみとするなど全体に抑制の効いた造形とする。幸寿門と同じく、境内における江戸前期の建築形式を伝える貴重な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012412"},{"id":"00012409","register_sub_id":"101","register_pk":"531733","name":"住吉大社斎館","kana":"すみよしたいしゃさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61201944,"lng":135.4934,"geo_status":"db","era":"文政11年(1828)／大正4年移築","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-735","desc":"神館背面に建つ。桁行七間梁間五間半、入母屋造本瓦葺で、上段の間を中心として前三室、後二室に座敷を配し、正面から側面に縁を廻す。組物は舟肘木、妻飾は木連格子で梅鉢懸魚を吊る。規模が大きく、境内中心部の歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012409"},{"id":"00012406","register_sub_id":"101","register_pk":"531730","name":"住吉大社五月殿","kana":"すみよしたいしゃさつきでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61171111,"lng":135.4925,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-732","desc":"神館域正面脇の御田北側にあって御田植神事に用いられる。桁行三間梁間二間、東西棟の切妻造本瓦葺、吹放ち形式で、境内で唯一壇上積基壇に建つ。飾気の少ない素木造に太い面取角柱や虹梁を用いて豪放に仕上げる。御田と一体で伝統ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012406"},{"id":"00005757","register_sub_id":"101","register_pk":"106745","name":"住吉大社神館","kana":"すみよしたいしゃしんかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区住吉2-9-89","lat":34.611938,"lng":135.493149,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積301㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0381","desc":"大正天皇の即位記念として建設。本宮の東方に位置する。南面する大床を備えた８畳の「玉座」の間を中心に複雑な屋根を架け，西面に唐破風造の玄関車寄を突き出す。各面に破風を見せる屋根構成と優美な深い軒線の意匠に特徴がある。設計は大阪府技師の池田實。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005757"},{"id":"00012415","register_sub_id":"101","register_pk":"531739","name":"住吉大社神館西門","kana":"すみよしたいしゃしんかんにしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61191944,"lng":135.4927,"geo_status":"db","era":"文政11年（1828）／明治中期移築","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-741","desc":"神館域の正面中央にある切妻造本瓦葺の四脚門。組物は実肘木付の三斗、妻飾は虹梁蟇股、冠木と棟木の間に虹梁を入れて蟇股と大瓶束を備える。素木造だが幸寿門に共通する形式で、虹梁や蟇股等の絵様も流麗で気品があり、神館域の表構えとしての格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012415"},{"id":"00012407","register_sub_id":"101","register_pk":"531731","name":"住吉大社神馬舎","kana":"すみよしたいしゃしんめしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61306944,"lng":135.4921,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-733","desc":"表参道に並行する北脇参道の西脇に建つ。桁行二間梁間三間、切妻造本瓦葺妻入で、北面に下屋を設けて屋根を葺下ろす。内部は主体部を土間の馬房、下屋を床張の馬丁部屋とする。現在も厩舎に用いられている、境内をかたちづくる伝統的な構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012407"},{"id":"00012418","register_sub_id":"101","register_pk":"531742","name":"住吉大社摂社大海神社北小門","kana":"すみよしたいしゃせっしゃたいかいじんじゃきたしょうもん","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61413056,"lng":135.4937,"geo_status":"db","era":"江戸後期／明治前期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-744","desc":"摂社大海神社の正面北脇を区切る瑞垣に開く。切妻造本瓦葺の棟門で、親柱を円柱、控柱を角柱とし、南小門と同じ規模･形式であるが、冠木と棟木の間に横桟を入れるなど細部に違いがある。小規模ながら南小門と一対になって、大海神社の社頭景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012418"},{"id":"00012417","register_sub_id":"101","register_pk":"531741","name":"住吉大社摂社大海神社南小門","kana":"すみよしたいしゃせっしゃたいかいじんじゃみなみしょうもん","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.613675,"lng":135.493575,"geo_status":"db","era":"江戸後期／明治14年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-743","desc":"摂社大海神社の正面南脇を区切る瑞垣に開く。切妻造本瓦葺の棟門で、親柱を円柱として角柱の控柱を前後に備える。棟木は冠木上に立てた束で受け、屋根には反りを付けて梅鉢懸魚を吊る。小規模ながら北小門と一対になって、大海神社の社頭景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012417"},{"id":"00012394","register_sub_id":"101","register_pk":"531718","name":"住吉大社摂社船玉神社本殿","kana":"すみよしたいしゃせっしゃふなたまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61210833,"lng":135.49260556,"geo_status":"db","era":"明治前期／昭和45年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、檜皮葺、建築面積7.5㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-720","desc":"神館域の正面脇に建つ。正面側面とも一間、切妻造檜皮葺妻入で、妻飾の豕扠首や本宮本殿と同形式の懸魚、内外陣に分かれる平面など住吉造に準じた形式とする。規模が大きく、鰹木と千木を載せた屋根が古式を強調し、境内中心部の復古的景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012394"},{"id":"00012425","register_sub_id":"101","register_pk":"531749","name":"住吉大社摂社若宮八幡宮鳥居","kana":"すみよしたいしゃせっしゃわかみやはちまんぐうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61216111,"lng":135.4939,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"石造、間口2.0m、高さ2.3m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-751","desc":"本宮域の後方、南中門の脇にある摂社若宮八幡宮前に立つ。柱に角柱を用い、貫を柱内で納め、反りのない島木･笠木を重ねる独特の形式とする。数多くの鳥居を有する境内にあって、類例少ない形式で希少である。建築年代が明らかな鳥居としても貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012425"},{"id":"00012419","register_sub_id":"101","register_pk":"531743","name":"住吉大社西大鳥居","kana":"すみよしたいしゃにしおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61258056,"lng":135.4916,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、間口6.1m、高さ6.4m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-745","desc":"境内正面の表参道入口に立つ。石造で、内転びの丸柱に貫を通し、反りのある島木･笠木を重ねた明神鳥居形式であるが、木割が太く安定感のある造形が古式を伝える。同社最大の大鳥居として参拝者に親しまれるとともに森厳な境内正面の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012419"},{"id":"00012396","register_sub_id":"101","register_pk":"531720","name":"住吉大社末社侍者社拝所・神饌所","kana":"すみよしたいしゃまっしゃおもとしゃはいしょ・しんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61215,"lng":135.4932,"geo_status":"db","era":"文政5年(1822)／昭和5年改修","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-722","desc":"境内中心部の本宮域と神館域の境に建つ。桁行六間梁間三間、切妻造銅板葺妻入で、前三間を神饌所、後三間を拝所とし、拝所最奥に本殿を安置する。拝所の左右には扉を開き、本宮域と神館域を結び付ける。同社の独特な境内の構成の核となる社殿の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012396"},{"id":"00012395","register_sub_id":"101","register_pk":"531719","name":"住吉大社末社侍者社本殿","kana":"すみよしたいしゃまっしゃおもとしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61215556,"lng":135.49324167,"geo_status":"db","era":"文政5年(1822)","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-721","desc":"侍者社拝所･神饌所にある境内唯一の屋内安置の本殿。正面側面とも一間、正面入母屋造、背面切妻造、檜皮葺妻入で、脇障子を立て高欄付の縁と木階七級を設ける。組物は舟肘木、妻飾は木連格子で本宮本殿と同形式の懸魚を吊る。細部は金物で豊かに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012395"},{"id":"00012401","register_sub_id":"101","register_pk":"531725","name":"住吉大社末社貴船社本殿","kana":"すみよしたいしゃまっしゃきぶねしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61208056,"lng":135.4943,"geo_status":"db","era":"江戸後期／昭和中期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-727","desc":"本宮域の背後に立聞社と並んで建つ。正面側面とも一間、切妻造本瓦葺妻入で、外陣正面に袖壁を付し、内外陣境は長押がなく虹梁に板扉を嵌込む。立聞社と同じ規模･形式であるが細部に違いがある。住吉造に倣った本殿形式の多彩な細部意匠の展開を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012401"},{"id":"00012403","register_sub_id":"101","register_pk":"531727","name":"住吉大社末社五社本殿","kana":"すみよしたいしゃまっしゃごしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61312778,"lng":135.49455,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-729","desc":"神苑の奥に建つ末社群の一つ。本瓦葺の五間社流造で、正面に縁と木階五級を設ける。妻は豕扠首で本宮本殿と同形式の懸魚を吊る。身舎各間は外陣を開放し、境に板扉を備える。境内後方を構成する末社群の景観にあって変化のある存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012403"},{"id":"00012402","register_sub_id":"101","register_pk":"531726","name":"住吉大社末社后土社本殿","kana":"すみよしたいしゃまっしゃごどしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61313611,"lng":135.49475556,"geo_status":"db","era":"江戸後期／昭和中期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-728","desc":"境内後方の神苑の奥に建つ末社群の一つ。正面側面とも一間、切妻造桟瓦葺妻入で、妻の豕扠首や反りのある屋根、土台建で見世棚風につくる外陣など、住吉造に準じた末社共通の形式を有する。立聞社や貴船社と同じく、住吉造系の本殿形式の多様性を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012402"},{"id":"00012400","register_sub_id":"101","register_pk":"531724","name":"住吉大社末社立聞社本殿","kana":"すみよしたいしゃまっしゃたちききしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61208889,"lng":135.4942,"geo_status":"db","era":"文政11年(1828)／昭和27年移築","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-726","desc":"本宮域の背後に貴船社と並んで建つ。正面側面とも一間、切妻造本瓦葺妻入で、柱は直接梁を受け、妻飾は豕扠首で梅鉢懸魚を吊る。面取角柱を土台建にして床を高く張り、外陣を見世棚造風にしながら、全体的には住吉造に倣った形式を有している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012400"},{"id":"00012399","register_sub_id":"101","register_pk":"531723","name":"住吉大社末社龍社本殿","kana":"すみよしたいしゃまっしゃたつしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61211944,"lng":135.4923,"geo_status":"db","era":"江戸後期／昭和4年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積6.7㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-725","desc":"神館域前方の神池のほとりに建つ。正面側面とも一間、切妻造本瓦葺妻入で、平面は内外陣に分かれ、外陣を開放し、境に板扉を構える。内陣は床を張らず、中央に井戸がある。水神と関わりの深い同社の信仰を端的に示す社殿で、形式も住吉造に準じている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012399"},{"id":"00012398","register_sub_id":"101","register_pk":"531722","name":"住吉大社末社楠珺社拝殿","kana":"すみよしたいしゃまっしゃなんくんしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61230556,"lng":135.49438889,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-724","desc":"楠珺社本殿の前面に建つ。切妻造平入の前面に入母屋造妻入を接続したＴ字形屋根をかけ、正面に向唐破風の向拝を付け、背面に祭壇を突出する。内部は土間の参拝空間とし、祭壇を床張とする。参拝の多様化に応じた大規模社殿で、信仰空間の新局面を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012398"},{"id":"00012397","register_sub_id":"101","register_pk":"531721","name":"住吉大社末社楠珺社本殿","kana":"すみよしたいしゃまっしゃなんくんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61225278,"lng":135.49437778,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.8㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-723","desc":"本宮域の背面にある神木の洞に差し込まれるように建つ。正面一間、切妻造銅板葺妻入で、屋根には反りを付け蕪懸魚を吊る。平面は内外陣に分かれ、外陣を開放し、境に板扉を構える。朱塗に飾金具を多用するなど小規模ながら装飾豊かな社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012397"},{"id":"00012404","register_sub_id":"101","register_pk":"531728","name":"住吉大社南絵馬殿","kana":"すみよしたいしゃみなみえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61245,"lng":135.4919,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-730","desc":"神池にかけられた反橋手前の表参道南側に建つ。桁行三間梁間一間、東西棟の切妻造本瓦葺、吹放ち形式で、太い大面取角柱や切石敷風にしたモルタル土間など、復古的な意匠でまとめられている。反橋と調和し、同社を象徴する社頭景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012404"},{"id":"00012420","register_sub_id":"101","register_pk":"531744","name":"住吉大社南大鳥居","kana":"すみよしたいしゃみなみおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61116667,"lng":135.49196389,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、間口5.7m、高さ6.4m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-746","desc":"境内側面の南からの参道入口に立つ。石造で、西鳥居と同じ形式の明神鳥居であるが、規模は一回り小さくつくる。東と北の大鳥居とは同規模で、四基一対で四至を結界する。境内の四方を固める主要な入口の一つとして、広大な境内の南面の構えの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012420"},{"id":"00012416","register_sub_id":"101","register_pk":"531740","name":"住吉大社南中門","kana":"すみよしたいしゃみなみちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61214722,"lng":135.49375833,"geo_status":"db","era":"江戸後期／昭和38年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口5.3m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-742","desc":"南門から石舞台と続く神館域裏の参道上に建つ。切妻造本瓦葺の四脚門で、組物を三斗、妻飾を虹梁蟇股とするなど旧規を踏襲するが、虹梁や蟇股等の絵様は動的で量感に富み、時代感覚を現している。同社最大の門で、境内南辺の歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012416"},{"id":"00012408","register_sub_id":"101","register_pk":"531732","name":"住吉大社南手水舎","kana":"すみよしたいしゃみなみてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.612,"lng":135.49233889,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積8.5㎡、手水鉢付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-734","desc":"表参道に並行する南脇参道の終点に建つ。桁行一間梁間一間、東西棟の入母屋造本瓦葺、吹放ち形式で、中央に水盤を据える。柱は几帳面取、組物は出組、軒は二軒扇垂木で格天井を張る。小規模ながら華麗なつくりで、伝統的な境内構成に彩りを添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012408"},{"id":"00012413","register_sub_id":"101","register_pk":"531737","name":"住吉大社南瑞籬門","kana":"すみよしたいしゃみなみみずがきもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61221944,"lng":135.4936,"geo_status":"db","era":"江戸後期／昭和38年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、銅板葺、間口4.4m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-739","desc":"本宮域の背面南端にある切妻造銅板葺の四脚門。組物を大斗肘木、妻飾を虹梁蟇股とするなど旧規を踏襲するが、虹梁や木鼻等の絵様は控えめな形状ながら極太で力強く、時代感覚を現している。第一殿の脇に建ち、境内中心部の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012413"},{"id":"00012423","register_sub_id":"101","register_pk":"531747","name":"住吉大社南脇参道角鳥居","kana":"すみよしたいしゃみなみわきさんどうかくとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61201944,"lng":135.4913,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造、間口4.6m、高さ5.1m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-749","desc":"南脇参道の入口に立つ。幸寿門前の角鳥居の形式を踏襲する石造の明神鳥居で、規模･形式とも寸分違わず北脇参道角鳥居と同じである。北脇参道角鳥居と左右一対で中央の西大鳥居の脇を固める、同社の境内正面の構成に不可欠な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012423"},{"id":"00014503","register_sub_id":"101","register_pk":"513917","name":"聖贖主教会（博愛社礼拝堂）","kana":"せいあがないぬしきょうかい（はくあいしゃれいはいどう）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市淀川区十三元今里三丁目63-4他","lat":34.7218,"lng":135.47608056,"geo_status":"db","era":"昭和11年／同62年・平成26年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積265㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0874","desc":"ヴォーリズ建築事務所設計のロマネスク調の鉄筋コンクリート造教会。外観は正面バラ窓、鐘楼塔屋とタレットが特徴的。当初は一階は社会福祉のために使用し、二階以上の教会と区切っていた。アウトフレームにより礼拝堂は意匠平明で落ち着いた空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014503"},{"id":"00002951","register_sub_id":"101","register_pk":"103941","name":"清学院庫裏","kana":"せいがくいんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区北旅龍町西1丁3-13","lat":34.59111447,"lng":135.482819,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0189","desc":"不動堂の南面と東面に接続した鍵形平面の住居建築で，不動堂側面にあたる南面に式台玄関を設け，奥に八畳間２室を配し，玄関南側を土間とする。切妻造で，不動堂南面から延びた部分は，つし２階で虫籠窓を設けた町家の外観とし，市街地の寺院の特色が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002951"},{"id":"00002950","register_sub_id":"101","register_pk":"103940","name":"清学院不動堂","kana":"せいがくいんふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区北旅龍町西1丁3-13","lat":34.59118088,"lng":135.48277639,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0188","desc":"桁行・梁間とも２間半の小仏堂で，通りに西面して建つ。切妻造・本瓦葺，平入，軸部は角柱とし，内部は８畳間で後方半間に通仏壇を構え，中央に軒唐破風付きの宮殿形厨子を置く。虹梁や木鼻の細部様式から江戸末期と考えられる。類例の少ない修験道場の建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002950"},{"id":"00002952","register_sub_id":"101","register_pk":"103942","name":"清学院門","kana":"せいがくいんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区北旅龍町西1丁3-13","lat":34.59113794,"lng":135.48274525,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口1.7m、左右塀付","structure_material":"木造","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0190","desc":"元禄２年（１６８９）の堺大絵図に「山伏清学院」とあり，江戸時代を通じての修験道場で，建物は江戸末期のものと考えられる。門は１間１戸の薬医門で，垂木に反りがある軽快な意匠とする。庫裏玄関前の前庭を囲うように建ち，市街地の街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002952"},{"id":"00009340","register_sub_id":"101","register_pk":"194133","name":"善龍寺山門","kana":"ぜんりゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町2-1-17","lat":34.66111004,"lng":135.51157243,"geo_status":"db","era":"文化7年／昭和前期移築","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0549","desc":"境内南面、天王寺七坂の一つ口縄坂沿いに建つ。間口二・七メートルの薬医門形式で、切妻造本瓦葺とし、左右に潜付袖塀を付す。架構は冠木上に架けた男梁に三斗をおいて妻虹梁を受け、妻飾には雲紋彫刻化した蟇股を飾る。良材を用い、意匠も優れた山門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009340"},{"id":"00007246","register_sub_id":"101","register_pk":"108228","name":"大光寺山門","kana":"だいこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町2-6","lat":34.660118,"lng":135.51098052,"geo_status":"db","era":"寛延2","year":1749,"year_source":"db","year_min":1749,"year_max":1749,"year_label":null,"structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0475","desc":"松屋町筋に西面する一間薬医門で、切妻造本瓦葺とする。間口２．８ｍで、潜戸付の袖塀を両脇に付ける。女梁を挿し肘木状に作り、男梁上、大斗肘木を介し、虹梁と軒桁を支持する。軒は一軒繁垂木。妻と中備は笈形付の虹梁大瓶束で、妻と中備の笈形の意匠を違える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007246"},{"id":"00002799","register_sub_id":"101","register_pk":"103789","name":"大光寺太子館","kana":"だいこうじたいしかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府吹田市岸部中5-10-10","lat":34.780518,"lng":135.539185,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0179","desc":"真宗寺院にある聖徳太子を祀る木造２階建の仏堂。地元の工匠の手になると考えられるが，１階を大壁で縦長窓の洋風意匠，２階を真壁で柱頭に舟肘木を置き軒を反らせる和風意匠とする新機軸で，洋風意匠の在郷への浸透を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002799"},{"id":"00013612","register_sub_id":"101","register_pk":"504983","name":"建水分神社摂社南木神社築地塀","kana":"たけみくまりじんじゃせっしゃなぎじんじゃついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字水分1060","lat":34.45996944,"lng":135.63146111,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、総延長41m","structure_material":"鉄筋コンクリート造","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0816","desc":"拝殿の背後の東西から延びて本殿の側背面を囲う鉄筋コンクリート造桟瓦葺の塀。側面塀の後方は地形なりに登り、段上の背面塀に接続する。全体を漆喰で塗込め、基壇、柱、頭繋ぎなどを現し、妻の破風なども丁寧につくる。本殿周りの静謐な空間を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013612"},{"id":"00013611","register_sub_id":"101","register_pk":"504965","name":"建水分神社摂社南木神社拝殿及び幣殿","kana":"たけみくまりじんじゃせっしゃなぎじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字水分1060","lat":34.46009444,"lng":135.63143056,"geo_status":"db","era":"昭和15年／平成16年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0815","desc":"本殿前に北面して建つ。正面五間側面二間、切妻造銅板葺、正面三間向拝付。向拝中央間は屋根を切欠いて一段高く向唐破風屋根を付す。四周に縁を廻し、背面両端に一間四方の室が突出し中央に唐破風屋根の幣殿が接続する。特異な形式ながら端正な意匠の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013611"},{"id":"00013610","register_sub_id":"101","register_pk":"504964","name":"建水分神社摂社南木神社本殿","kana":"たけみくまりじんじゃせっしゃなぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字水分1060","lat":34.46,"lng":135.63145,"geo_status":"db","era":"昭和13年／平成16年・同29年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0814","desc":"建水分神社境内にある楠木正成を祀る摂社。本殿は境内中段南側に北面して建つ。一間社春日造銅板葺で、正側面に腰高く縁を廻して脇障子を建て、縁の両端に至る幅広の木階を付して浜縁を設ける。楠公顕彰の機運が高まる中再興された、端正なつくりの近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013610"},{"id":"00013613","register_sub_id":"101","register_pk":"504984","name":"建水分神社宝庫","kana":"たけみくまりじんじゃほうこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字水分1060","lat":34.46061111,"lng":135.63159722,"geo_status":"db","era":"大正9年頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0817","desc":"境内下段の参道沿いに西面して建つ。木造平屋建、切妻造妻入桟瓦葺で、正面に切妻屋根の玄関を付す。外壁は漆喰で軒先まで塗込めて軒下に鉢巻を廻し、側面に窓を四連開いて腰を竪板張とする。内部は一室で中央に陳列棚を設ける。参道入口の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013613"},{"id":"00015063","register_sub_id":"101","register_pk":"529341","name":"千早神社小宮（旧本殿）","kana":"ちはやじんじゃこみや（きゅうほんでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41618611,"lng":135.65287778,"geo_status":"db","era":"明治7年／昭和56年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0934","desc":"社務所の北に建ち、参道に南面する一間社流造銅板葺の旧本殿。三方に縁を廻らし、脇障子を建て、組物は大斗肘木、軒は一軒繁垂木、妻飾は豕扠首。肘木や虹梁に絵様を入れ、庇の中備に菊と波の彫刻を付す。小規模ながら装飾豊富な社殿で、境内の旧景を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015063"},{"id":"00015062","register_sub_id":"101","register_pk":"529340","name":"千早神社社務所","kana":"ちはやじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41607778,"lng":135.65278611,"geo_status":"db","era":"昭和7年／昭和50年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0933","desc":"参道に北面する社務所。平屋建銅板葺で、式台棟、授与所棟、主体部のそれぞれ切妻屋根を正面にみせる。内部南西は続き間座敷で南東に床を構え、南西に縁を廻らす。軒薄く簡明ながれも螻羽が深い切妻屋根を前方に突出して強調した力強い外観が特徴的な社務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015062"},{"id":"00015061","register_sub_id":"101","register_pk":"529339","name":"千早神社手水舎","kana":"ちはやじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41612222,"lng":135.65299167,"geo_status":"db","era":"昭和3年／昭和50年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、面積1.6㎡","structure_material":"木造","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0932","desc":"本殿の北西、参道に南面する切妻造平入銅板葺の手水舎。主柱を棟木まで延ばし、前後に低い控柱を立てて貫で固める。二段の腕木で軒桁を支え、主柱間に楣を入れ欄間は横連子。中央に自然石組の手水鉢を置く。簡明ながら存在感を示す手水舎で境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015061"},{"id":"00015059","register_sub_id":"101","register_pk":"529337","name":"千早神社拝殿及び渡廊","kana":"ちはやじんじゃはいでんおよびわたろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41585,"lng":135.65330556,"geo_status":"db","era":"昭和3年／昭和50年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0930","desc":"本殿正面に建つ拝殿及び渡廊。桁行三間梁間二間切妻造銅板葺で上段の本殿に向け渡廊を設ける。側廻りは背面中央に御扉を建てる他は全て吹放ちとし、流麗な意匠の錺金具を付した御扉のみが背景の森から浮かび上がる。大江新太郎の設計による斬新な形式の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015059"},{"id":"00015058","register_sub_id":"101","register_pk":null,"name":"千早神社本殿","kana":"ちはやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.4158,"lng":135.65339722,"geo_status":"db","era":"昭和3年／昭和50年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0929","desc":"史跡千早城跡二の丸に位置する神社本殿。設計は大江新太郎。境内南東端に西面して建つ桁行三間梁間二間切妻造妻入銅板葺で棟に千木と堅魚木を置く。内部は内・外陣とし外陣前面に縁を付し、扉などに流麗な意匠の錺金具を飾る。全体に木柄細く端正な姿の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015058"},{"id":"00015060","register_sub_id":"101","register_pk":"529338","name":"千早神社末社","kana":"ちはやじんじゃまっしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41596111,"lng":135.65329167,"geo_status":"db","era":"昭和７年／昭和50年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.5㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0931","desc":"本殿の北西に位置し、基壇上に南面して建つ桁行三間梁間一間切妻造平入銅板葺。螻羽を深くつくり、大棟に長い樋棟を載せる。柱は円柱で腰長押、内法長押で固め、南面各間には錺金具を付した扉戸を開ける。妻に飾る縦長の懸魚や桁隠など本殿意匠に通じる末社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015060"},{"id":"00007245","register_sub_id":"101","register_pk":"108227","name":"超心寺山門","kana":"ちょうしんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-15-1","lat":34.66088193,"lng":135.510986,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.1m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0474","desc":"松屋町筋に西面する一間薬医門で、切妻造本瓦葺とする。間口３．１ｍで、袖塀を両脇に付ける。女梁を挿し肘木状に作り、男梁上、大斗肘木を介して、虹梁と軒桁を支持。妻や中備は流水や雲紋風に彫られた蟇股とする。軒は一軒繁垂木。たちの高い薬医門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007245"},{"id":"00014271","register_sub_id":"101","register_pk":"509661","name":"伴林氏神社手水舎","kana":"ともばやしのうじのじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.57528056,"lng":135.61114722,"geo_status":"db","era":"昭和16年／同58年・平成8年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0862","desc":"境内南の大鳥居外側西に位置する手水舎で、靖国神社手水舎を移築したもの。入母屋造銅板葺、二軒吹寄垂木、四隅に三本一組で円柱を立て、内法長押上に連子の欄間を嵌める。近代らしい洗練された意匠の大規模な手水舎で、靖国神社の遺構としても貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014271"},{"id":"00014269","register_sub_id":"101","register_pk":"509659","name":"伴林氏神社拝殿及び幣殿","kana":"ともばやしのうじのじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.57566667,"lng":135.61122778,"geo_status":"db","era":"昭和16年／同58年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積219㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0860","desc":"式内社の本殿南に南面して建つ近代の大型拝殿。入母屋造平入銅板葺、三間の向拝に千鳥破風を載せる。正面五間、側面四間、奥に幣殿が突出し、翼廊を介し東に祭器所、西に神饌所を配す。台湾檜素木造、格天井御影石敷の広い土間で、近代らしい堂々とした造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014269"},{"id":"00014268","register_sub_id":"101","register_pk":"509658","name":"伴林氏神社本殿","kana":"ともばやしのうじのじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.57578889,"lng":135.61123889,"geo_status":"db","era":"昭和15年／同36年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0859","desc":"市野山古墳の西にある式内社本殿で大伴氏の祖神を祀る。正面三間春日造で向拝に切妻破風を載せる。二軒繁垂木、大棟に堅魚木、千木が鬼板外側に付く。木階廻りを幣殿に繋ぎ屋内とする。西の靖国神社として整備された台湾檜素木造の格式ある近代大型本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014268"},{"id":"00014270","register_sub_id":"101","register_pk":"509660","name":"伴林氏神社棟門及び透塀","kana":"ともばやしのうじのじんじゃむねもんおよびすかしべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.57585833,"lng":135.61123333,"geo_status":"db","era":"昭和15年／同58年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"棟門 木造、銅板葺、間口2.1m 透塀 木造、銅板葺、総延長55m","structure_material":"棟門 木造","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0861","desc":"本殿の北、東、西方を囲む透塀と棟門。基壇の葛石上に建ち本殿を囲む神域を形成する。透塀は銅板葺で、地覆と内法貫間に大和打の板を嵌める。北面中央を切り上げて開く棟門は、切妻造平入銅板葺で、中備に蟇股を掲げる。境内社殿群を構成して景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014270"},{"id":"00014272","register_sub_id":"101","register_pk":"509662","name":"伴林氏神社若宮八幡宮社殿(旧澤田尋常小学校奉安殿)","kana":"ともばやしのうじのじんじゃわかみやはちまんぐうしゃでん（きゅうさわだじんじょうしょうがっこうほうあんでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.575875,"lng":135.61099722,"geo_status":"db","era":"昭和15年／同48年・平成15年移築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.7㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0863","desc":"伴林氏神社本殿の西に建つ社殿で元は奉安殿。木造で一間社神明造、銅板葺で千木、堅魚木、鞭掛を備える。素木造で木柄太く、棟持柱は転びなく直立する。高欄付き榑縁を廻し、木階を設け擬宝珠付親柱を構える。木造奉安殿の希少な遺構で神明造による好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014272"},{"id":"00000065","register_sub_id":"101","register_pk":"101055","name":"日本基督教団大阪教会","kana":"にほんきりすときょうだんおおさかきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市西区江戸堀1-23-17","lat":34.68944487,"lng":135.49346393,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄骨造・煉瓦造・コンクリート造3階建塔屋付、銅板葺、建築面積674㎡","structure_material":"鉄骨造・煉瓦造・コンクリート造3階建塔屋付","registered":"1996.12.20(平成8.12.20)","register_no":"27 － 0005","desc":"ヴォーリズ設計の鉄骨・煉瓦・コンクリート混合造の教会堂で，背後に塔屋が建つ。ロマネスク様式を基調とする意匠で構成され，数少ない大正期の赤煉瓦建物として親しまれている。正面妻壁のバラ窓や，玄関上部の半円形の飾り窓で構成される外観に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000065"},{"id":"00004997","register_sub_id":"101","register_pk":"105987","name":"日本基督教団大阪住吉教会","kana":"にほんきりすときょうだんおおさかすみよしきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区東粉浜2-21-3","lat":34.61896342,"lng":135.49250079,"geo_status":"db","era":"大正8／昭和6増改造","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、スレート葺、建築面積180㎡、塔付","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0329","desc":"南海本線と阪堺線に挟まれた一画に所在。大正８年建設の切妻造，下見板張，上げ下げ窓の礼拝堂及び牧師館の前面に寄棟造，モルタル塗の木造２階建を増築し，正面右寄りに塔を上げる。改造はあるが，玄関脇の丸窓や礼拝堂祭壇などが昭和初期意匠の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004997"},{"id":"00007890","register_sub_id":"101","register_pk":"108870","name":"日本基督教団島之内教会","kana":"にほんきりすときょうだんしまのうちきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区東心斎橋1-38","lat":34.67215586,"lng":135.50499712,"geo_status":"db","era":"昭和3／昭和中期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリートブロック造3階建、建築面積384㎡","structure_material":"鉄筋コンクリートブロック造3階建","registered":"2009.11.02(平成21.11.02)","register_no":"27-0535","desc":"大阪市内の繁華街に建つ。３階建、陸屋根。正面に大階段を構え、６本の角柱を並べる玄関を造り、化粧ブロックを使用し、正面性を打ち出す。設計者が開発した「中村式鉄筋コンクリートブロック構造」による建築で、近代における建築構造の発展過程を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007890"},{"id":"00010663","register_sub_id":"101","register_pk":"201237","name":"日本基督教団天満教会","kana":"にほんきりすときょうだんてんまきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市北区天神西町20-1","lat":34.694683,"lng":135.510832,"geo_status":"db","era":"昭和4年／昭和34年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積362㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0618","desc":"天満宮近傍に位置する中村式鉄筋コンクリート造四階建。正面は略対称形で、階段室前面を矩形意匠で構成する。内部一階を集会室とし、二・三階分の礼拝堂に架ける楕円アーチの梁に連続アーチを刳抜く。構造及び意匠に昭和初期の建築思潮の一端を示す教会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010663"},{"id":"00015490","register_sub_id":"101","register_pk":"533505","name":"日本基督教団南大阪教会塔","kana":"にほんきりすときょうだんみなみおおさかきょうかい とう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目30-2","lat":34.63559722,"lng":135.51580556,"geo_status":"db","era":"昭和3年／昭和56年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積11㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2025.08.06(令和7.08.06)","register_no":"27 - 0948","desc":"阿倍野に位置する教会の塔。設計は村野藤吾。鉄筋コンクリート造３階建で外壁モルタル塗仕上。方形平面で南面中央部の迫出に円と十字を組合わせた帯状透彫を付し、頂部に十字架を立てる。村野の処女作の一部で、鉄筋コンクリート造形への志向を示す貴重な塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015490"},{"id":"00001629","register_sub_id":"101","register_pk":"102619","name":"日本フリーメソジスト教団大阪日本橋キリスト教会","kana":"にほんふりーめそじすときょうだんおおさかにっぽんばしきりすときょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区日本橋1-20-4","lat":34.66582493,"lng":135.50581234,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積342㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0090","desc":"堺筋の南の起点，日本橋一丁目の南西角近くに東面して建つ。玄関部の尖頭アーチの入口，３階の５連の尖頭アーチ窓などゴシックスタイルを基調とするが，堺筋沿いの街路景観に溶け込むように正面ファサードを概ね平板につくっている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001629"},{"id":"00000545","register_sub_id":"101","register_pk":"101535","name":"念仏寺本堂","kana":"ねんぶつじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区上本町4-2-41","lat":34.67074114,"lng":135.52046351,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建，瓦葺，152㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"27 － 0034","desc":"大阪の繁華街に立地する中規模の浄土宗本堂。平面は，内外陣・余間等規格に則って配置する標準的な作品である。細部彫刻等は時代相応の構成になる。旧城下の寺町の北限を示す遺構であり，入母屋造の大屋根を見せる外観は，整った境内とも広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000545"},{"id":"00014636","register_sub_id":"101","register_pk":"515178","name":"法明寺庫裏","kana":"ほうみょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目20他","lat":34.66985833,"lng":135.56052778,"geo_status":"db","era":"寛政9年（1797）／昭和中期・同61年改修","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造2階建、瓦葺、建築面積258㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0880","desc":"旧深江村の集落西寄りに所在する浄土宗寺院の庫裏。入母屋造平入桟瓦葺のつし二階建、正背面に下屋を設け、入母屋造式台玄関を構える。内部は九間取座敷に広い土間と板間を並べ、竹の節欄間を備えるなど古風な面を持つ。本堂と並んで歴史的な境内景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014636"},{"id":"00014637","register_sub_id":"101","register_pk":"515179","name":"法明寺鐘楼","kana":"ほうみょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目20他","lat":34.66965556,"lng":135.56013611,"geo_status":"db","era":"正徳3年（1713）／大正元年・平成26年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造、瓦葺、面積11㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0881","desc":"旧深江村の西寄りにある浄土宗寺院の鐘楼。境内南西に位置する。切妻造本瓦葺、一軒半繁垂木、虹梁蟇股と絵様肘木を備え、角柱几帳面取下端粽付。基壇は切込み矧ぎ石積で、北面に切込み階段を備える。軸組太く絵様繰形整う建築年代明らかな鐘楼として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014637"},{"id":"00014635","register_sub_id":"101","register_pk":"515177","name":"法明寺本堂","kana":"ほうみょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目20他","lat":34.66987222,"lng":135.56030278,"geo_status":"db","era":"元禄7年（1694）／大正元年・昭和38年改修","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0879","desc":"旧深江村の集落西寄りに所在する浄土宗寺院の本堂。元は錣屋根、火災後に寄棟造とした平入本瓦葺。一軒半繁垂木で反りは伸びやか。中央間を広くとった正面五間向拝付。内陣柱は太い円柱で、脇仏壇含む内陣は平面凸型で一段高く近世浄土宗本堂の特徴を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014635"},{"id":"00014638","register_sub_id":"101","register_pk":"515180","name":"法明寺薬医門","kana":"ほうみょうじやくいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目20他","lat":34.66957778,"lng":135.56024444,"geo_status":"db","era":"寛政7年（1795）／大正元年・平成14年改修","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0882","desc":"旧深江村の浄土宗寺院の表門。奈良街道から参道を引き込んで境内南面に開く、入母屋造平入本瓦葺の薬医門。格天井で、梁は三通り架け、控柱に水引虹梁を架ける。小規模ながら絵様繰形整う建築年代明らかな門で、集落及び街道沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014638"},{"id":"00007240","register_sub_id":"101","register_pk":"108222","name":"萬福寺山門","kana":"まんぷくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-9","lat":34.662891,"lng":135.51118804,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0469","desc":"松屋町筋に西面する一間薬医門。間口２．９ｍ幅に本柱を建て、男梁と女梁間に大斗肘木を入れ、妻には蟇股を置く。二軒半繁垂木で、切妻造本瓦葺。地垂木や男梁、女梁の鼻先に絵様を施し、華やかな印象を与える。蟇股には植物紋様を彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007240"},{"id":"00011158","register_sub_id":"101","register_pk":"205265","name":"水無瀬神宮神庫","kana":"みなせじんぐうしんこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.884849,"lng":135.672689,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0644","desc":"境内南西隅に北面して建つ。桁行二間半梁間二間、土蔵造二階建、寄棟造桟瓦葺で、正面中央の戸口に下屋を設け、漆喰塗の扉を開く。切石積基礎上に建ち、正面に石階四級を設け、外壁漆喰塗として水切一段を廻らせる。近代に再編された境内景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011158"},{"id":"00011160","register_sub_id":"101","register_pk":"205267","name":"水無瀬神宮神門及び築地塀","kana":"みなせじんぐうしんもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.885065,"lng":135.672618,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"神門 木造、瓦葺、間口2.8m 築地塀 瓦葺、総延長5.0m、北方潜戸付","structure_material":"神門 木造","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0646","desc":"参道の突当りに構える門と築地塀。神門は一間薬医門、切妻造本瓦葺で、女梁に斗を置いて男梁を支持し、男梁上に長い撥束を立て、斗と実肘木で棟木を受ける。築地塀も本瓦葺で土壁に定規線五筋を引き、北塀に潜りを開く。離宮跡地の由緒に相応しい格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011160"},{"id":"00011159","register_sub_id":"101","register_pk":"205266","name":"水無瀬神宮手水舎","kana":"みなせじんぐうちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.885127,"lng":135.672706,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、面積5.5㎡、手水鉢付","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0645","desc":"境内正面の神門北東に南北棟で建ち、桁行長を三・〇メートルとのばした方一間平面で、入母屋造桟瓦葺とし、石製の手水鉢と井戸枠を置く。角柱に内法長押を廻らして舟肘木を置き、格天井を組み、妻飾は木蓮格子に梅鉢懸魚を吊る。本格的な形式をもつ手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011159"},{"id":"00011157","register_sub_id":"101","register_pk":"205264","name":"水無瀬神宮拝殿及び幣殿","kana":"みなせじんぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.88487,"lng":135.673076,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0643","desc":"拝殿は桁行四間の入母屋造の正面に三間向拝を付け、北側に庇状の張出しと神饌所、背面に桁行二間の幣殿を設ける。土間式で基壇周囲に高欄を廻らせる。小屋を虹梁豕扠首、組物舟肘木として古風とし、伸びやかな曲線の蟇股を飾るなど設計者角南隆の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011157"},{"id":"00011156","register_sub_id":"101","register_pk":"205263","name":"水無瀬神宮本殿","kana":"みなせじんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.88485,"lng":135.673278,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、銅板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0642","desc":"境内南東奥に西面して建つ。桁行三間梁間二間で、四方に縁を廻らして脇障子をたて、前面に浜床を設ける。柱上に舟肘木を置き、二軒繁垂木とする。内部は内外陣に二分し、外陣は折上小組格天井を張り、正側面に板唐戸を開く。簡素な意匠に格調を備えた社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011156"},{"id":"00001724","register_sub_id":"101","register_pk":"102714","name":"御幸森天神宮透塀","kana":"みゆきもりてんじんぐうすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区桃谷3-10-5","lat":34.66043439,"lng":135.53456943,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、銅板葺、延長32m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0096","desc":"拝殿背後から延びて幣殿及び本殿を巡る塀。高さ約１ｍの切石積に建ち、折れ曲がり延長１７間で、挿肘木を用い銅板葺の屋根を架ける。各間に連子窓を設け腰板壁とする。柱・垂木などは本殿、拝殿などと同様な大面取りとして意匠を統一する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001724"},{"id":"00001723","register_sub_id":"101","register_pk":"102713","name":"御幸森天神宮拝殿","kana":"みゆきもりてんじんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区桃谷3-10-5","lat":34.66030735,"lng":135.53456172,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0095","desc":"亀腹基壇上に建つ入母屋造平入り拝殿で、正面に緩やかな曲線からなる唐破風造の向拝を備える。内部は１室で背面左右の庇を「のりと座」及び「祭器庫」とする。本殿、幣殿と一連の建築であり、昭和初期における鎌倉復古様式神社建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001723"},{"id":"00001722","register_sub_id":"101","register_pk":"102712","name":"御幸森天神宮幣殿","kana":"みゆきもりてんじんぐうへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区桃谷3-10-5","lat":34.66035252,"lng":135.53456814,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0094","desc":"本殿・拝殿間を繋ぐ桁行２間、両流造の幣殿。側面に菱格子窓を構え腰板壁とする。内部は木舞下地の化粧屋根裏とし、上下２段の虹梁を渡した架構に特色がある。本殿・拝殿同様な良質の檜を用い、素木の端正な美しさをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001722"},{"id":"00001721","register_sub_id":"101","register_pk":"102711","name":"御幸森天神宮本殿","kana":"みゆきもりてんじんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区桃谷3-10-5","lat":34.66038576,"lng":135.53456814,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0093","desc":"三間社流造で屋根正面に千鳥破風と軒唐破風を付ける組物は身舎を軒支輪付の出組、庇を三斗組とする。身舎庇ともに実肘木に大仏様の繰形を施し、蟇股や木鼻の形態も古式である。透塀越しに望めるように床を高めている。設計は奈良の吉田種次郎と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001721"},{"id":"00013609","register_sub_id":"101","register_pk":"504963","name":"薬樹山延命寺宝物館","kana":"やくじゅさんえんめいじほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市神ガ丘492","lat":34.42606389,"lng":135.59399167,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0813","desc":"市街南東にある真言宗寺院の宝物館で境内南の高台に建つ。木造二階建寄棟造桟瓦葺で、四周に下屋を廻し正面に切妻玄関を付す。外壁は漆喰塗で軒は扇垂木。内部は中央を区画して像を安置し四周の回廊壁際に陳列棚を設ける。城郭の櫓を思わせる重厚なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013609"},{"id":"00004272","register_sub_id":"101","register_pk":"105262","name":"吉野薬師堂","kana":"よしのやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府豊能郡能勢町吉野110","lat":34.98641427,"lng":135.47596879,"geo_status":"db","era":"天文24","year":1555,"year_source":"db","year_min":1555,"year_max":1555,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積73㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"27 － 0299","desc":"集落ほぼ中央に南面して建つ。方３間，寄棟造，茅葺（鉄板仮葺）で，側柱は大面取り角柱，仏壇前面両脇は太い円柱とし，内部は前方梁間２間を広間，奥は中央を仏壇，両脇を小間に仕切る。中世の部材を残すとともに，集落の歴史景観上欠くことのできない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004272"},{"id":"00001834","register_sub_id":"101","register_pk":"102824","name":"瀧安寺鳳凰閣","kana":"りゅうあんじほうおうかく","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府箕面市箕面公園内","lat":34.84269624,"lng":135.47198017,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積130㎡、塔屋付","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0099","desc":"切妻造・桟瓦葺，平屋建で，その北端に宝形造の楼閣をあげた形態で，平等院鳳凰堂翼廊の気分が表現されている。設計は武田五一，施工は高橋組。箕面山の中腹に位置し，石垣を高く築いた敷地に建ち，箕面川の渓流とともに優れた景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001834"},{"id":"00012222","register_sub_id":"101","register_pk":"353022","name":"若山神社本殿","kana":"わかやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府三島郡島本町大字広瀬1497","lat":34.891384,"lng":135.654335,"geo_status":"db","era":"文化4年(1807)／大正11年改修","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"27-717","desc":"平野部を見下ろす景勝地に東面して建つ。三間社流造で、中央柱間を広くとる。身舎は円柱で、軒は二軒繁垂木、屋根はかつては檜皮葺だったと伝える。向唐破風造の向拝には、近代らしい装飾意匠の彫刻を施しており、特徴的な形式の神社本殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012222"},{"id":"00007274","register_sub_id":"101","register_pk":"108256","name":"上善寺経蔵","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.41341065,"lng":135.31650863,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、面積28㎡","structure_material":"土蔵造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0503","desc":"本堂の西方に東面して建つ。宝形造本瓦葺、正面４．９ｍ奥行５．０ｍ規模で、正面に一間向拝を付ける。土蔵造で白漆喰仕上げとし、正面中央の出入口に両開格子戸と、漆喰仕上げの引分戸をたてる。内部は低い板床を張り、天井は棹縁天井、漆喰壁で柱や貫を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007274"}];
